comms.text:
@1 וַחֲיָא יַעֲקֹב בְּאַרְעָא דְמִצְרַיִם שְׁבַע עֶשְׂרֵי שְׁנִין וַהֲווֹ יוֹמֵי יַעֲקֹב שְׁנֵי חַיוֹהִי מְאָה וְאַרְבְּעִין וּשְׁבַע שְׁנִין:
@2 וּקְרִיבוּ יוֹמֵי יִשְׂרָאֵל לִמְמַת וּקְרָא לִבְרֵהּ לְיוֹסֵף וַאֲמַר לֵהּ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינָיךְ שַׁוִּי כְעַן יְדָךְ תְּחוֹת יַרְכִּי וְתַעְבֵּד עִמִּי טִיבוּ וּקְשׁוֹט לָא כְעַן תִּקְבְּרִנַּנִי בְּמִצְרַיִם:
@3 וְאִשְׁכּוּב עִם אֲבָהָתַי וְתִטְּלִנַנִּי מִמִּצְרַיִם וְתִקְבְּרִנַנִּי בִּקְבֻרְתְּהוֹן וַאֲמַר אֲנָא אֶעְבַּד כְּפִתְגָּמָךְ:
@4 וַאֲמַר קַיֵּם לִי וְקַיִים לֵהּ וּסְגִיד יִשְׂרָאֵל עַל רֵישׁ עַרְסָא:
@5 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וַאֲמַר לְיוֹסֵף הָא אֲבוּךְ שְׁכִיב מְרָע וּדְבַר יָת תְּרֵין בְּנוֹהִי עִמֵּהּ יָת מְנַשֶּׁה וְיָת אֶפְרָיִם:
@6 וְחַוִּי לְיַעֲקֹב וַאֲמַר הָא בְּרָךְ יוֹסֵף אֲתָא לְוָתָךְ וְאִתַּקַף יִשְׂרָאֵל וִיתֵיב עַל עַרְסָא:
@7 וַאֲמַר יַעֲקֹב לְיוֹסֵף אֵל שַׁדַּי אִתְגְּלִי לִי בְלוּז בְּאַרְעָא דִכְנָעַן וּבָרִיךְ יָתִי:
@8 וַאֲמַר לִי הָא אֲנָא מַפְשִׁינָךְ וְאַסְגִּנָּךְ וְאֶתְּנִנָּךְ לְכִנְשַׁת שִׁבְטִין וְאֶתֵּן יָת אַרְעָא הָדָא לִבְנָיךְ בַּתְרָךְ אַחֲסָנַת עֲלָם:
@9 וּכְעַן תְּרֵין בְּנָיךְ דְּאִתְיְלִידוּ לָךְ בְּאַרְעָא דְמִצְרַיִם עַד מֵיתִי לְוָתָךְ לְמִצְרַיִם דִּילִי אִנּוּן אֶפְרַיִם וּמְנַשֶּׁה כִּרְאוּבֵן וְשִׁמְעוֹן יְהוֹן קֳדָמָי:
@10 וּבְנָיךְ דִּי תוֹלִיד בַּתְרֵיהוֹן דִּילָךְ יְהוֹן עַל שׁוּם אֲחוּהוֹן יִתְקְרוּן בְּאַחֲסַנְתְּהוֹן:
@11 וַאֲנָא בְּמֵיתִי מִפַּדָן מִיתַת עָלַי רָחֵל בְּאַרְעָא דִּכְנַעַן בְּאָרְחָא בְּעוֹד כְּרוּבָא דְאַרְעָא לְמֵיעַל לְאֶפְרָת וּקְבָרִתַּהּ תַּמָּן בְּאֹרַח אֶפְרָת הִיא בֵּית לָחֶם:
@12 וַחֲזָא יִשְׂרָאֵל יָת בְּנֵי יוֹסֵף וַאֲמַר מַן אִלֵּין:
@13 וַאֲמַר יוֹסֵף לַאֲבוּהִי בְּנַי אִנּוּן דִּי יְהַב לִי יְיָ הָכָא וַאֲמַר קָרֵבִנּוּן כְּעַן לְוָתִי וְאֵבָרֵכִנּוּן:
@14 וְעֵינֵי יִשְׂרָאֵל יְקָרָן מִסֵּיבוּ לָא יִכּוּל לְמֶחֱזֵי וְקָרִיב יָתְהוֹן לְוָתֵהּ וְנַשִּׁיק לְהוֹן וְגַפִּיף לְהוֹן:
@15 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף לְמֶחֱזֵי אַפָיךְ לָא סְבָרִית וְהָא אַחֲזִי יָתִי יְיָ אַף יָת בְּנָיךְ:
@16 וְאַפֵּיק יוֹסֵף יָתְהוֹן מִן קֳדָמוֹהִי וּסְגִיד עַל אַפּוֹהִי עַל אַרְעָא:
@17 וּדְבַר יוֹסֵף יָת תַּרְוֵיהוֹן יָת אֶפְרַיִם בִּימִינֵהּ מִשְׂמָאלָא דְיִשְׂרָאֵל וְיָת מְנַשֶּׁה בִשְׂמָאלֵהּ מִימִינָא דְיִשְׂרָאֵל וְקָרֵיב לְוָתֵהּ:
@18 וְאוֹשִׁיט יִשְׂרָאֵל יָת יְמִינֵהּ וְשַׁוִּי עַל רֵישָׁא דְאֶפְרַיִם וְהוּא זְעֵירָא וְיָת שְׂמָאלֵהּ עַל רֵישָׁא דִּמְנַשֶּׁה אַחְכִּמִינּוּן לִידוֹהִי אֲרֵי מְנַשֶּׁה בּוּכְרָא:
@19 וּבְרִיךְ יָת יוֹסֵף וַאֲמָר יְיָ דִי פְלָחוּ אֲבָהָתַי קֳדָמוֹהִי אַבְרָהָם וְיִצְחָק יְיָ דְזַן יָתִי מִדְאִיתָנִי עַד יוֹמָא הָדֵין:
@20 מַלְאָכָא דִי פְרַק יָתִי מִכָּל בִּישָׁא יְבָרֵךְ יָת עוּלֵמַיָּא וְיִתְקְרֵי בְהוֹן שְׁמִי וְשׁוּם אֲבָהָתַי אַבְרָהָם וְיִצְחָק וּכְנוּנֵי יַמָּא יִסְגוּן בְּגוֹ בְנֵי אֱנָשָׁא עַל אַרְעָא:
@21 וַחֲזָא יוֹסֵף אֲרֵי שַׁוִּי אָבוּהִי יַד יְמִינֵהּ עַל רֵישָׁא דְאֶפְרַיִם וּבְאֵישׁ בְּעֵינוֹהִי וְסָעֵד יְדָא דְאָבוּהִי לְאַעֲדָאָה יָתַהּ מֵעַל רֵישָׁא דְאֶפְרַיִם לְאַנָחוּתַהּ עַל רֵישָׁא דִמְנַשֶּׁה:
@22 וַאֲמַר יוֹסֵף לְאָבוּהִי לָא כֵן אַבָּא אֲרֵי דֵין בּוּכְרָא שַׁו יְמִינָךְ עַל רֵישֵׁהּ:
@23 וְסָרֵיב אָבוּהִי וַאֲמַר יְדַעְנָא בְרִי יְדַעְנָא אַף הוּא יְהֵי לְעַמָּא וְאַף הוּא יִסְגֵּי וּבְרַם אָחוּהִי זְעִירָא יִסְגֵּי מִנֵּהּ וּבְנוֹהִי יְהוֹן שַׁלִּיטִין בְּעַמְמַיָּא:
@24 וּבְרֵיכִנּוּן בְּיוֹמָא הַהוּא לְמֵימַר בָּךְ יְבָרֵךְ יִשְׂרָאֵל לְמֵימַר יְשַׁוִּינָךְ יְיָ כְּאֶפְרַיִם וְכִמְנַשֶּׁה וְשַׁוִּי יָת אֶפְרַיִם קֳדָם מְנַשֶּׁה:
@25 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף הָא אֲנָא מָאִית וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדְכוֹן וְיָתֵיב יָתְכוֹן לְאַרְעָא דַאֲבָהַתְכוֹן:
@26 וַאֲנָא יְהָבִית לָךְ חוּלַק חַד יַתִּיר עַל אַחָיךְ דִּי נְסֵיבִית מִידָא דֶאֱמוֹרָאָה בִּצְלוֹתִי וּבְבָעוּתִי:
@27 וּקְרָא יַעֲקֹב לִבְנוֹהִי וַאֲמַר אִתְכַּנָשׁוּ וַאֲחַוֵּי לְכוֹן יָת דִּי יְעָרַע יָתְכוֹן בְּסוֹף יוֹמַיָּא:
@28 אִתְכַּנָּשׁוּ וּשְׁמָעוּ בְּנֵי יַעֲקֹב וְקַבִּילוּ אוּלְפַן מִן יִשְׂרָאֵל אֲבוּכוֹן:
@29 רְאוּבֵן בּוּכְרִי אַתְּ חֵילִי וְרֵישׁ תָּקְפִּי לָךְ הֲוָה חָזֵי לְמִסַּב תְּלָתָא חוּלָקִין בְּכֵירוּתָא כְּהֻנְתָּא וּמַלְכוּתָא:
@30 עַל דַאֲזַלְתָּא לָקֳבֵל אַפָּיךְ הָא כְמַיָּא בְּרַם לָא אַהֲנֵיתָא חוֹלָק יַתִּיר לָא תִסַּב אֲרֵי סְלֶקְתָּא בֵּית מִשְׁכָּבֵי אָבוּךְ בְּכֵן אֲחֶלְתָּא לְשִׁוּוּיִי בְּרִי סְלֶקְתָּא:
@31 שִׁמְעוֹן וְלֵוִי אַחִין גַּבְרִין גִּבָּרִין בְּאַרַע תּוֹתָבוּתְהוֹן עֲבָדוּ גְּבוּרָא:
@32 בְּרָזְהוֹן לָא הֲוַת נַפְשִׁי בְּאִתְכַּנְשֵׁהוֹן לִמְהַךְ לָא נְחָתִית מִן יְקָרִי אֲרֵי בְרָגְזְהוֹן קְטָלוּ קְטוֹל וּבִרְעוּתְהוֹן תַּרָעוּ שׁוּר סַנְּאָה:
@33 לִיט רָגְזְהוֹן אֲרֵי תַקִיף וְחֵמַתְהוֹן אֲרֵי קַשְׁיָא אֲפַלְגִנוּן בְּיַעֲקֹב וְאֵבַדָרִנוּן בְּיִשְׂרָאֵל:
@34 יְהוּדָה אַתְּ אוֹדֵיתָא וְלָא בְהֵיתְתָא בָּךְ יוֹדוּן אַחָיךְ יְדָךְ תִּתְקֵף עַל בַּעֲלֵי דְבָבָךְ יִתְבַּדְרוּן סַנְאָךְ יְהוֹן מְחַזְרִין קְדַּל קֳדָמָךְ וִיְהוֹן מְקַדְמִין לְמִשְׁאַל בִּשְׁלָמָךְ בְּנֵי אָבוּךְ:
@35 שִׁלְטוֹן יְהֵי בְשֵׁרוּיָא וּבְסוֹפָא יִתְרַבָּא מַלְכָּא מִדְבֵית יְהוּדָה אֲרֵי מִדִין קַטְלָא בְּרִי נַפְשָׁךְ סְלֶקְתָּא יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵיתָא וְלֵית מַלְכוּ דִתְזַעְזְעִנֵהּ:
@36 לָא יַעֲדֵי עָבֵד שָׁלְטַן מִדְבֵית יְהוּדָה וְסַפְרָא מִבְּנֵי בְנוֹהִי עַד עָלְמָא עַד דְיֵיתֵי מְשִׁיחָא דְדִילֵהּ הִיא מַלְכוּתָא וְלֵהּ יִשְׁתַּמְעוּן עַמְמַיָּא:
@37 יַסְחַר יִשְׂרָאֵל לְקַרְתֵּהּ עַמָּא יִבְנוּן הֵיכְלֵהּ יְהוֹן צַדִּיקַיָּא סְחוֹר סְחוֹר לֵהּ וְעָבְדֵי אוֹרַיְתָא בְּאוּלְפַן עִמֵּהּ יְהֵי אַרְגְוָן טַב לְבוּשׁוֹהִי כְּסוּתֵהּ מֵילָא מֵילָא צְבַע זְהוֹרִי:וצִבְעוֹנִין:
@38 ??? יְסַמְקוּן טּוּרוֹהִי בְּכַרְמוֹהִי יְטוּפוּן נַעֲווֹהִי בַּחֲמָר יְחַוְרָן בִּקְעֲתֵהּ בְּעִיבוּר וּבְעֶדְרֵי עָנָא:
@39 זְבוּלֻן עַל סְפַר יַמְמַיָּא יִשְׁרֵי וְהוּא יְכַבֵּשׁ מְחוֹזִין בִּסְפִינַן וְטוּב יַמָּא יֵיכוּל וּתְחוּמֵהּ יְהֵי מָטֵי עַל צִידוֹן:
@40 יִשָּׂשׂכָר עַתִּיר בְּנִכְסִין וְאַחֲסַנְתֵּהּ בֵּין תְּחוּמַיָּא:
@41 וַחֲזָא חוּלָקָא אֲרֵי טַב וְיָת אַרְעָא אֲרֵי מְעַבְּדָא פֵירִין וִיכַבֵּשׁ מָחוֹזֵי עַמְמַיָּא וִישֵׁיצֵי יָת דַּיָרֵיהוֹן וּדְאִשְׁתַּאֲרוּן בְּהוֹן יְהוֹן לֵהּ פַּלְחִין וּמַסְּקֵי מַסִּין:
@42 מִדְּבֵית דָּן יִתְבְּחַר וִיקוּם גַּבְרָא בְּיוֹמוֹהִי יִתְפְּרֵק עַמֵּהּ וּבִשְׁנוֹהִי יְנוּחוּן כַּחֲדָא שִׁבְטַּיָּא דְיִשְׂרָאֵל:
@43 יְהֵי גַבְרָא דְיִתְבְּחַר וִיקוּם מִדְּבֵית דָּן אֵימְתֵהּ תִּתְרְמֵי עַל עַמְמַיָּא וּמְחָתֵהּ תִּתְקֵף בִּפְלִשְׁתָּאֵי כְּחִיוֵי חוּרְמָן יִשְׁרֵי עַל אָרְחָא וּכְפִתְנָא יִכְמוֹן עַל שְׁבִילָא יְקַטֵּיל גִּבָּרֵי מַשִׁרְיַת פְּלִשְׁתָּאֵי פָּרָשִׁין עִם רַגְלָאִין יְעַקֵר סוּסָוָן וּרְתִכִּין וִימַגֵּר רוֹכְבֵיהוֹן לַאֲחוֹרָא:
@44 לְפוּרְקָנָךְ סַבָּרִית יְיָ:
@45 מִדְבֵית גָד מַשִׁרְיַת מְזַיְנִין כַּד יַעַבְרוּן יָת יַרְדְנָא קֳדָם אֲחֵיהוֹן לִקְרָבָא וּבְנִכְסִין סַגִּיאִין יְתוּבוּן לְאַרְעֲהוֹן:
@46 דְאָשֵׁר טָבָא אַרְעֵהּ וְהוּא מְרַבְיָא בְּתַפְנוּקֵי מַלְכִין:
@47 נַפְתָּלִי בְּאַרַע טָבָא יִתְרְמֵי עַדְבֵהּ וְאַחְסַנְתֵּהּ תְּהֵי מְעַבְּדָא פֵירִין יְהוֹן מוֹדַן וּמְבָרְכִין עֲלֵיהוֹן:
@48 בְּרִי דְיִסְגֵּי יוֹסֵף בְּרִי דְיִתְבָּרַךְ כְּגֹפֶן דִּנְצִב עַל עֵינָא דְמַיָּא תְּרֵין שִׁבְטִין יִפְּקוּן מִבְּנוֹהִי יְקַבְּלוּן חוּלָקָא וְאַחֲסַנְתָּא:
@49 וְאִתְמַרְרוּ יָתֵהּ וְנַקְמוֹהִי וְאָעִיקוּ לֵהּ גֻבְרִין גִּבָּרִין בַּעֲלֵי פַלְגוּתָא:
@50 וְתָבַת בְּהוֹן נְבִיאוּתֵהּ עַל דְּקַיֵּם אוֹרַיְתָא בְּסִתְרָא וְשַׁוִּי בְתוּקְפָא רוֹחֲצָנֵהּ בְּכֵן יִתְרְמָא דְהַב עַל דְּרָעוֹהִי וְאַחֲסִין מַלְכוּתָא וּתְקֵיף דָּא הֲוַת לֵהּ מִן קֳדָם אֵל תַּקִיפָא דְיַעֲקֹב דִּי בְמֵימְרֵהּ זַן אֲבָהָן וּבְנִין זַרְעָא דְיִשְׂרָאֵל:
@51 מֵימַר אֱלָהָא דְאָבוּךְ יְהֵי בְסַעְדָךְ וְיָת שַׁדַּי וִיבָרְכִנָּךְ בִּרְכַן דְּנַחֲתָן מִטַּלָּא דִשְׁמַיָּא מִלְעֵלָא בִּרְכַן דְנַגְדַן מִמַעֲמַקֵי אַרְעָא מִלְרָע בִּרְכְּתָא דְאָבוּךְ וּדְאִמָּךְ:
@52 בִּרְכְּתָא דְאָבוּךְ יִתּוֹסְפָן עַל בִּרְכְּתָא דִילִי בָּרִיכוּ אֲבָהָתַי דַחֲמִידוּ לְהֶן רַבְרְבַיָּא דְמִן עָלְמָא יֶהֶוְיַן כָּל אִלֵּין לְרֵישָׁא דְיוֹסֵף וּלְגַבְרָא פָּרִישָׁא דַאֲחוֹהִי:
@53 בִּנְיָמִין בְּאַרְעֵהּ תִּשְׁרֵי שְׁכִנְתָּא וּבְאַחֲסַנְתֵּהּ יִתְבְּנֵי מַקְדְשָׁא בְּצַפְרָא וּבְפַנְיָא יְהוֹן מְקָרְבִין כַּהֲנַיָּא קָרְבָּנָא וּבְעִדַּן רַמְשָׁא יְהוֹן מְפַלְגִין מוֹתַר חוּלְקְהוֹן מִשְׁאַר קָדְשַׁיָּא:
@54 כָּל אִלֵּין שִׁבְטַיָּא דְיִשְׂרָאֵל תְּרֵין עֲסַר וְדָא דְמַלֵּיל לְהוֹן אֲבוּהוֹן וּבָרִיךְ יָתְהוֹן גְבַר דִּי כְבִרְכְּתֵהּ בָּרֵךְ יָתְהוֹן:
@55 וּפַקֵד יָתְהוֹן וַאֲמַר לְהוֹן אֲנָא מִתְכְּנֵשׁ לְעַמִּי קְבָרוּ יָתִי לְוַת אֲבָהָתִי בִּמְעַרְתָּא דִי בַחֲקַל עֶפְרוֹן חִתָּאָה:
@56 בִּמְעַרְתָּא דִי בַחֲקַל כָּפֶלְתָּא דִי עַל אַפֵּי מַמְרֵא בְּאַרְעָא דִכְנָעַן דִי זְבַן אַבְרָהָם יָת חַקְלָא מִן עֶפְרֹן חִתָּאָה לְאַחֲסָנַת קְבוּרָא:
@57 תַּמָּן קְבָרוּ יָת אַבְרָהָם וְיָת שָׂרָה אִתְּתֵהּ תַּמָּן קְבָרוּ יָת יִצְחָק וְיָת רִבְקָה אִתְּתֵהּ וְתַמָּן קְבָרִית יָת לֵאָה:
@58 זְבִינֵי חַקְלָא וּמְעַרְתָּא דִי בֵהּ מִן בְּנֵי חִתָּאָהּ:
@59 וְשֵׁיצֵי יַעֲקֹב לְפַקָּדָא יָת בְּנוֹהִי וּכְנַשׁ רַגְלוֹהִי לְעַרְסָא וְאִתְנְגִיד וְאִתְכְּנִישׁ לְעַמֵּהּ:
@60 וּנְפַל יוֹסֵף עַל אַפֵּי אָבוּהִי וּבְכָא עֲלוֹהִי וּנְשַׁק לֵהּ:
@61 וּפַקֵּיד יוֹסֵף יָת עַבְדוֹהִי יָת אַסְוָתָא לְמֶחְנַט יָת אָבוּהִי וְחָנְטוּ אַסְוָתָא יָת יִשְׂרָאֵל:
@62 וּשְׁלִימוּ לֵהּ אַרְבְּעִין יוֹמִין אֲרֵי כֵּן שְׁלִימוּ יוֹמֵי חֲנִיטַיָּא וּבְכוֹ יָתֵהּ מִצְרָאֵי שַׁבְעִין יוֹמִין:
@63 וַעֲבָרוּ יוֹמֵי בְכִיתֵהּ וּמַלִיל יוֹסֵף עִם בֵּית פַּרְעֹה לְמֵימָר אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינֵיכוֹן מַלִּילוּ כְעַן קֳדָם פַּרְעֹה לְמֵימָר:
@64 אַבָּא קַיֵּים עָלַי לְמֵימָר הָא אֲנָא מָאִית בְּקִבְרִי דְאַתְקֵנִית לִי בְּאַרְעָא דִכְנָעַן תַּמָּן תִּקְבְּרִנָנִי וּכְעַן אֶסַּק כְּעַן וְאֶקְבַּר יָת אַבָּא וְאֵ יתוּב:
@65 וַאֲמַר פַּרְעֹה סַק וּקְבוֹר יָת אֲבוּךְ כְּמָא דְקַיֵּים עֲלָךְ:
@66 וּסְלֵיק יוֹסֵף לְמִקְבַּר יָת אָבוּהִי וּסְלִיקוּ עִמֵּהּ כָּל עַבְדֵי פַרְעֹה סָבֵי בֵיתֵהּ וְכֹל סָבֵי אַרְעָא דְמִצְרָיִם:
@67 וְכֹל בֵּית יוֹסֵף וַאֲחוֹהִי וּבֵית אָבוּהִי לְחוֹד טַפְלְהוֹן וְעָנְהוֹן וְתוֹרֵיהוֹן שְׁבָקוּ בְּאַרְעָא דְגשֶׁן:
@68 וּסְלִיקוּ עִמֵּהּ אַף רְתִכִּין אַף פָּרָשִׁין וַהֲוָה מַשְׁרִיתָא סַגִּיאָה לַחֲדָא:
@69 וַאֲתוֹ עַד בֵּית אִדְרֵי דְאָטָד דִּי בְּעִבְרָא דְיַרְדְנָא וּסְפָדוּ תַמָּן מִסְפֵּד רַב וְתַקִּיף לַחֲדָא וְעָבַד לַאֲבוּהִי אֶבְלָא שַׁבְעָא יוֹמִין:
@70 וַחֲזָא יָתֵב אַרְעָא כְנַעֲנָאָה יָת אֶבְלָא בְּבֵית אִדְרֵי דְאָטָד וַאֲמָרוּ אָבֵל תַּקִּיף דֵּין לְמִצְרָאֵי עַל כֵּן קְרָא שְׁמַהּ אָבֵל מִצְרַיִם דִּי בְּעִבְרָא דְיַרְדְנָא:
@71 וַעֲבָדוּ בְּנוֹהִי לֵהּ כֵּן כְּמָא דִי פַּקֵדִנּוּן:
@72 וּנְטָלוּ יָתֵהּ בְּנוֹהִי לְאַרְעָא דִכְנַעַן וּקְבָרוּ יָתֵהּ בִּמְעָרַת חֲקַל כָּפֶלְתָּא דִי זְבַן אַבְרָהָם יָת חַקְלָא לְאַחֲסָנַת קְבוּרָא מִן עֶפְרֹן חִתָּאָה עַל אַפֵּי מַמְרֵא:
@73 וְתַב יוֹסֵף לְמִצְרַיִם הוּא וַאֲחוֹהִי וְכָל דִּסְלִיקוּ עִמֵּהּ לְמִקְבַּר יָת אָבוּהִי בָּתַר דִּקְבַר יָת אָבוּהִי:
@74 וַחֲזוֹ אֲחֵי יוֹסֵף אֲרֵי מִית אֲבוּהוֹן וַאֲמָרוּ דִּלְמָא יִטַּר לָנָא דְבָבוּ יוֹסֵף וְאֲתָבָא יָתֵיב לָנָא יָת כָּל בִּישְׁתָא דִי גְמַלְנָא יָתֵהּ:
@75 וּפַקִידוּ לְוַת יוֹסֵף לְמֵימָר אָבוּךְ פַּקֵּד קֳדָם מוֹתֵהּ לְמֵימָר:
@76 כְּדֵין תֵּימְרוּן לְיוֹסֵף בְּבָעוּ שְׁבוֹק כְּעַן לְחוֹבָא אַחָיךְ וְלַחֲטָאֵהוֹן אֲרֵי בִישְׁתָא גְמָלוּךְ וּכְעַן שְׁבוֹק כְּעַן לְחוֹבָא עַבְדֵי אֱלָהָא דְאָבוּךְ וּבְכָא יוֹסֵף בְּמַלָלוּתְהוֹן עִמֵּהּ:
@77 וַאֲזָלוּ אַף אֲחוֹהִי וּנְפָלוּ קֳדָמוֹהִי וַאֲמָרוּ הָא אֲנַחְנָא לָךְ לְעַבְדִין:
@78 וַאֲמַר לְהוֹן יוֹסֵף לָא תִדַחֲלוּן אֲרֵי דַחֲלָא דַּיְיָ אֲנָא:
@79 וְאַתּוּן חֲשַׁבְתּוּן עֲלַי בִּישָׁא מִן קֳדָם יְיָ אִתְחַשְׁבַת לְטָבָא בְּדִיל לְמֶעְבַּד כְּיוֹמָא הָדֵין לְקַיָּמָא עַם סַגִּי:
@80 וּכְעַן לָא תִדַחֲלוּן אֲנָא אֵזוּן יָתְכוֹן וְיָת טַפְלְכוֹן וְנַחֵם יָתְהוֹן וּמַלֵּיל תַּנְחוּמִין עַל לִבְּהוֹן:
@81 וִיתֵיב יוֹסֵף בְּמִצְרַיִם הוּא וּבֵית אָבוּהִי וַחֲיָא יוֹסֵף מְאָה וַעֲסַר שְׁנִין:
@82 וַחֲזָא יוֹסֵף לְאֶפְרַיִם בְּנִין תְּלִיתָאִין אַף בְּנֵי מָכִיר בַּר מְנַשֶּׁה אִתְיְלִידוּ וְרַבִּי יוֹסֵף:
@83 וַאֲמַר יוֹסֵף לַאֲחוֹהִי אֲנָא מָאִית וַיְיָ מִדְכַּר דְּכִיר יָתְכוֹן וְיִסַק יָתְכוֹן מִן אַרְעָא הָדָא לְאַרְעָא דִי קַיִים לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@84 וְאוֹמֵי יוֹסֵף יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְּכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַּרְמַי מִכָּא:
@85 וּמִית יוֹסֵף בַּר מְאָה וַעֲסַר שְׁנִין וַחֲנָטוּ יָתֵהּ וְשָׂמוּהִי בָאֳרוֹנָא בְּמִצְרָיִם: חזק:

@1 **ויחי יעקב**. טעם קריאת שמו יעקב אחר אשר אמר אליו ה' (ל''ה י') לא יקרא וגו'. לא יעקב יאמר עוד שמך, כבר כתבתי בפרשת וישלח בפירוש פסוק לא יקרא וגו', כי לצד שם נפשו הקבועה בו אשר שמה יעקב כידוע מדבריהם (ברכות ז:) שפירשו בפסוק (תהלים מו) אשר שם שמות בארץ, ולצד שעודנה באיבו לזה לא יעקר שמה וב' שמות יקראו לו:
@1 **אלא** שיש לנו לחקור זאת במה יבחר ה' לזמנים יקרא לו יעקב ולזמנים ישראל, הן אמת כי בעדת ישראל מצינו שישתנה להם השם כפי מעשיהם כשעושים רצונו של מקום בשם ישראל יכנה אותם ולהפך יקרא שמם יעקב וכן הוא רמוז בדבריהם, (זהר בלק די:) וטעם זה לא יוצדק ביעקב כי ישר פעלו בתמידות:
@1 **אכן** להיות שענף המושכל אשר נתעצם יעקב להשיגו שבאמצעותו בשם ישראל יתכנה הוא בחינת קדושה עליונה ותמצא כי המין המאושר ההוא ימאס לבחינת הדאגה והעצבון והשפלות כי ממקום השמחה והמנוחה והגדולה באה, והיה לאות בין עיניך יום שבת למנוחה אשר צוה ה' את בני ישראל והוא לטעם נשמה יתירה ולצד שממקום עליון באה, יצו ה' להרחיק היגון והכעם ולקרא לשבת עונג, והן הדברים עצמם נאמרים ביעקב בהשגתו שם עליון השם יגיד כי צוה ה' אתו את הנשמה העליונה בעלת שם זה של ישראל ומשכנה בו הוא כל זמן שאין שם עצבון וענף הנגדי קצת לשמחה ולשלימות הקדושה והטהרה, ובהעדר כן וינפש יוצאה ממנו כיציאת נשמה יתירה של יום שבת ובאותו זמן לא יקרא לו ישראל, כי בעלת השם הלכה לה ואינה אז ויקרא שמו יעקב, ותשוב עוד הנשמה ההיא באמצעות הכנת והצעת המוכן כהשבת נשמה יתירה בכל שבת ושבת באמצעות הכנת יום המקודש. ובזה תלך לבטח להשכיל טעם בכל מקום אשר בשם יעקב יתכנה הוא לסיבה אשר יארע שם דבר מבחינת העצב והיגון, וארשום לך קצת מהמקומות להאיר לך וזה יצא ראשונה. תחלת דבר טוב ה' בפ' וישלח אמר אליו שמך יעקב פירוש אז יהיה שמו יעקב לצד שהיה אז באבילות אמו כמאמרם ז''ל (ב''ד פ' פ''ב) שאמרו כי אומרו ויברך אותו יכוין על ברכת אבלים ולצד זה יקרא שמו יעקב, ולזה תמצא שבכל אותו פרשה קרא ה' שמו יעקב, וגם בזמן מיתת רחל נקרא שמו יעקב דכתיב (ל''ה כ') ויצב יעקב מצבה על קבורתה, ואחר ששלמו ימי העצב קרא ה' שמו ישראל דכתיב (שם כ''א) ויסע ישראל, בשכון ישראל, והגם שאמר שם ויהיו בני יעקב, יש לך לדעת כי כשיהיו הבנים במדריגה פחותה לצד מעשיהם הגם שהאב יתכנה בשם ישראל הם יתכנו בשם יעקב, ובמה שלפנינו לצד מעשה שהיה שעשה ראובן קרא להם שם בני יעקב ומה שאמר עוד שם (כ''ז) ויבא יעקב אל יצחק אביו לצד שהיה לפני יצחק אביו לא נהג בו הכתוב השררה והגדולה הנרמזת בשם ישראל, וכן תמצא שאמרו במדרש תהלים ילקוט סי' תתע''ה וז''ל אילו היה אברהם קיים היאך היה יצחק מנהיג שררה וכן כל האבות והצדיקים וכו' עד כאן. הנך רואה כי תסתלק השררה לפני אביו ולטעם זה קרא שמו יעקב, וכן מה שקרא לו שם יעקב בפרשת וישב יודיע הכתוב כי כל זמן שהיה יעקב אז בארץ כנען היה ביגון ואנחה ובמדריגת שם יעקב זולתי בזמנים מועטים אשר רשם הכתוב בהם שם ישראל כאומרו (ל''ז ג') וישראל אהב וגו' אז היה שמח והוכן בלי עצב לקרות לו שם ישראל. ותמצא כי משנמכר יוסף לא נקרא שמו ישראל זולת שלשה פעמים (מ''ג ו') ויאמר ישראל למה הרעותם וגו', ויאמר יהודה אל ישראל אביו, (שם ח') ויאמר אליהם ישראל אביהם, (שם י''א) וצריכין להדרש כי דבר אליהם דרך שררה לצד ההכרח שראה שלא חשו לצערו ונשתרר עליהם ורמז כי לא ימחול להם לצד שהוא אביהם, גם שיקבלו דבריו. ומעת התבשרו ביוסף ותחי רוח יעקב (מ''ה כ''ז) ונחה עליו רוח ה' ותיכף אמר הכתוב ויאמר ישראל, (שם כ''ח) ויסע ישראל, ויאמר אלהים לישראל, (מ''ו) עד שנתבשר בגלות וקבל עליו השבר חזר ליקרא יעקב זולת בעת אשר נגלה אליו יוסף לרוב השמחה הגדולה כינה ה' אותו בשם ישראל דכתיב (שם כ''ט) ויעל לקראת ישראל אביו, ויאמר ישראל אמותה הפעם, (שם ל') ומשם ואילך לא נקרא עוד שם ישראל כל ימי היותו בארץ מצרים עד יום שהגיע עת לכתו לעולמו. ומה שאמר (מ''ז) וישב ישראל בארץ מצרים יכוין אל כללות בניו שיתיחם אליהם שם ישראל כשיהיו בדרך יושר, וגדול כח הבנים מכח אביהם כי הבנים כל אשר יטיבו דרכם יקרא להם שם ישראל להיותם רבים מה שאין כן יעקב ידקדק בקריאת שמו לרמוז בקריאתו זמן מצבו, ולא נקרא בשם ישראל כל זמן היותו בארץ מצרים עד עת שקרבו ימיו למות אז נקרא שמו ישראל לצד תוסף רוחם, והוא סוד הגדלת נפש אדם בעת מיתתו, (זהר ח''א ריח:) לזה אמר ויקרבו ימי ישראל, וישתחו ישראל. וכלך לדרך זה להשכיל בכל מקום אשר יקרא לו שם הוא שמו לסיבה אשר תשכיל שמה. ועיין בדברי הזוהר (שם ריא:) ותמצא סעד לדברינו. וכל זה הוא דרך פשט, ויש דברים בגו כפי רוחניות הדברים והמשכיל יבין:
@1 **ויחי יעקב בארץ מצרים וגו'**. צריך לדעת למה הוצרך לומר מה שחיה בארץ מצרים. ועוד קשה לא היה צריך לומר אלא ויהי ימי יעקב וגו' קמ''ז וגו' ואני יודע לפי החשבון כי שבע עשרה שנה חיה בארץ מצרים למה שקדם בהודעה בפרשת ויגש דכתיב (ט') שני מגורי שלשים ומאת שנה. עוד למה הוצרך לומר **שני חייו** ולא הספיק לומר ויהי ימי יעקב. ואולי כי לצד שכל ימי יעקב לא נח ולא שקט כי משנולד נולד שטנו ועדיין לא שקעה שמשו עמד לבן ואלה מוסיף לרע לו, ואחריו הוקם על צערה של דינה, ועוד לו ויבא רוגז אבידת יוסף, הוא שאמר הכתוב ויחי יעקב בארץ מצרים י''ז שנה אלו היו חייו ולא קודם, וסמך לזה אומרו **ויהי ימי יעקב שני חייו** לרמוז שהן הנה היו ימיו שהיה לו בהם חיות, והוא אומרו ויהי ימי יעקב פירוש אותם י''ז שנה שני חייו פי' שהי' לו בהם חיים. ונמשכת ימי יעקב עם מה שלמטה ממנה ימי יעקב וגו' שבע וגו':
@1 **עוד** ירצה על דרך אומרם ז''ל (תדא''ר פ''ה) כל מי שסוף ימיו בטובה כאלו כל ימיו בטובה, והוא טעם (איוב ח') והיה ראשיתך וגו' ואחריתך ישגה מאוד גם אומרו (קהלת ז') טוב אחרית דבר וגו', והוא אומרו **ויחי יעקב** חיים של שלוה בארץ מצרים בזה היה בעיניו שהיו ימי יעקב שני חייו פי' שנים של חיים כל ימיו שהם ז' שנים וגו'. וטעם אומרו **ויהי** לשון צער יכוין לומר שהגם שהיו ימיו בצער אף על פי כן חזרו בעיניו להיות כולם של חיים:
@1 **ויש** לנו לחקור זאת למה שינה הכתוב סדר מספר שנותיו של יעקב מסדר הלקוח במספר שני הצדיקים שמקדים מספר גדול למספר קטן באברהם כתיב (כ''ה ז') מאת שנה ושבעים שנה וגו', ביצחק כתיב (ל''ה כ''ח) מאת שנה ושמנים שנה, בשרה כתיב (כ''ג א') מאה שנה ועשרים וגו'. ואולי כי הקדים מנין המועט שהוא האחרון שבו היה בשלוה וחיים טובים:
@1 **עוד** יכוין הכתוב באופן אחר כי ימים שהיה יעקב לבו נכון ומאויו שלמים בכל חייו הם ימים שבע וארבעים שנה, והטעם הוא כאומרם ז''ל כי את רחל אהב והיא בת זוגו אשר בחר יעקב בה ובבניה אשר תוליד כאומרו (ל''ז ג') אהב את יוסף מכל וגו', ויש בזה גם כן סוד עתיק, והיה לך לאות כי כל זמן שלא היה יוסף וישם שק על מתניו, ולכשתצרף מנין הימים שהיה בחברת רחל גם שנים שהיה יוסף עמו תמצא מ''א שנים, כי עשרים שנה עשה בבית לבן צא מהם שבע עד שנשא רחל נשארו י''ג ובהם נבלעו משני יוסף שש שנים כי כשנולד התחיל יעקב לעבוד בצאנו של לבן דכתיב (ל''א מ''א) ושש שנים בצאנך וכשמכרוהו היה בן י''ז שנה צא מהם ו' נשארו י''א וי''ג הרי כ''ד, וי''ז במצרים הרי מ''א, ושש שנים שהיה יעקב בפעוטות שהם ימים שהלב שמח וריקם מיגון הרי מ''ז, והוא אומרו **ויהי ימי יעקב שני חייו** שהיו לו חיים שבע שנים וארבעים, ולזה בחר להקדים פרט המועט להודיע זה:
@1 **וטעם** אומרו **ויהי** לדרך זה, יכוין להודיע כי לא השלים יעקב אבינו כל ימי חייו החרוצים, והוא מאמרם ז''ל (ב''ר פ' ע''ד) כי לצד שאמר לא יחיה והכרית חיי רחל נחסרו לו ימיו ממנין שני יצחק שהיו ק''פ ל''ג שנה כמנין יחיה, לזה רמזה התורה צער חסרון שני הצדיק בתיבת ויהי:
@1 **ונשאר** לתת טעם הכתוב למה ימנה חשבון שני יעקב קודם שהגיע זמנו ליפטר כי הנך רואה כי אחר שמנה הכתוב ויהי ימי יעקב אמר אחריו מעשה השבעת יוסף ואחר כך אמר ויהי אחרי הדברים ויאמר ליוסף וגו' ומן הראוי לא היה להזכיר סכום ימיו עד יום מותו, ואולי כי נתכוין להודיע דבר שממנו הרגיש יעקב שקרבו ימיו למות שמצד זה קרא לבנו ליוסף וגו' ואמר **ויהי ימי יעקב שני חייו** וגו' פירוש לצד מה שקדם אליו מידיעת חיי יצחק שהיו ק''פ שנה גם שהרגיש הצדיק בשגגתו אשר שגג בקללה לא יחיה וידע בענשו כי האבות נביאים היו ורוח הקודש לובשתם ולזה כשעשה חשבון שני אביו והוציא מהם ל''ג חש לביאת יומו שקרב ויקרא לבנו וגו':
@1 **ובדרך** רמז יתבאר הכתוב למה שהודיע אלהים בבחינת יוסף כי הוא המשביר והוא שזן והחיה עם רב כמאמרו (נ' כ') להחיות עם רב, ובחינה זו תשלול היותה בעלת חוב לזולתה בבחינת ההשפעה לה, ולד שיעקב זן ופרנס את יוסף י''ז שנה דכתיב (ל''ז ב') בן י''ז וגו' לזה שילם הבחינה הלז והשפיע הוא ליעקב במדת תשלומי כפל כמה מדות מרובות י''ז שנה והוא שרמז **ויחי יעקב בארץ מצרים שבע עשרה שנה**, וזולת זה אפשר שהיו שלמים ימיו קודם לכן אלא לשלם יוסף טובת חסד שקבל ממנו ולזה טובי''ם השנים מהאחד כי כל אחד הטיב מספר טו''ב שנים ונכון לשלם זה לזה. ותמצא שאמרו ז''ל (זהר וישה קפב.) כי יוסף הוא בבחינת וא''ו מילוי וא''ו כידוע ליודעי נסתרות לה' אלהינו:
@2 **ויקרבו ימי וגו'**. כבר כתבתי בסמוך מנין ידע, ורמב''ן כתב שידע מהרגשת אפיסת כוחותיו. ואין דבריו ז''ל נראים כי כמה ימים יחיה אדם אחר שיתחיל להח לש:
@2 **עוד** יש לומר כי הרגיש מהדברים אשר יארעו לאדם קודם מותו על דרך אומרם ז''ל בספר הזוהר (ח''א ריז:) כי שלשים יום קודם מותו מעבירין ממנו הצלם ומעשה הובא שם שראה רשב''י ר' יצחק שעבר צלמו ממנו, והגם כי ידיעה זו מושללת מבני אדם הצדיקים מרגישים ויודעים כל דבר רוחני. עוד יתבאר הענין בדקדוק עוד אומרו **ויקרבו ימי** וכי בימים שייך לומר לשון קריבה:
@2 **אכן** כוונת הכתוב הוא על פי מה שכתב איש אלהים קדוש ה''ה הר''י לוריא זצוק''ל ומצאת כי תדרשנו בם' קהלת יעקב וז''ל ואמנם ידעת מהתחלקות הנשמות לכמה ניצוצות ובכל גלגול וגלגול באים קצת מהם וכפי מספר הניצוצות של הצלם כך מספר ימי חייו והימים שעושה בהם המצות נתקן ניצוץ אחד של הצלם ההוא כנגד היום ההוא והיום שאין עושה בו מצוה נשאר פגום ניצוץ ההוא של הצלם ההוא כנגד היום ההוא וכן על זה הדרך וכו' ע''כ. ומה מאד האירה הקדמה זו עיני משכיל בכמה פרטי החקירות. האחד האירה עינינו בסוד השינה כי היא לעלות ניצוץ שכנגד היום ההוא והוא סוד אומרם כי השינה א' מס' מהמיתה (ברכות נז:) ואין יציאת הניצוץ בהחלט מוכרת מהנשמה אלא שנפרד מהכל ועודנו נסרך ונסבך בנפש, וזה מחסד אל שכל ניצוץ שזכה ביומו הנה הוא רחוק מההפסד הגם שירשיע אדם אחריו וניצוץ אשר יעלה פגום הנה הוא יכול ליתקן על ידי תשובה ישוב הניצוץ ויתקן גם זה מחסדי המתחסד הוא אלהינו יתעלה שמו, גם האיר למול עינינו תשובת תרעומת גם בני אדם גם בני איש מה זאת עשה לנו אלקים מה נשתנו דורותינו מדורות הראשונים אשר שבעו חיים תשע מאות שנה ושלשים לאדם וכן בניו ובני בניו שמנה מאות ושבע מאות, ואנחנו המפליא בחיים לא יגיע למאה שנה, ועל פי ההקדמה הלז נחה דעת כל אדם, והמשל בזה למלך שחלק אבנים טובות הבאים מהמחצב לאומנים לתקנם בתכלית היופי וההכנה ולעשות להם משבצות זהב כדרך סגולות המלכים וגזר אומר כי האיש הזריז והמשתדל לעשות התיקון בכל ההשתדלות ובכל התיקון והיופי כאשר צוה המלך והיו לו האבנים הטובות לו לחלקו ונחלתו להשתעשע ולהתנאות בהם ונתן האבנים במספר הרבה מאוד לכל איש ואיש לא' נתן שלש מאות אלף ולא' שלש מאות וחמשים אלף הן חסר הן יתר וקבע להם הזמן אשר יספיק למלאכה יום אחד לכל אבן ואבן ובמלאת הימים ישלח המלך לקחת האבנים הטובות. ויהי כי שלמו ימי המלאכה פקד המלך אומניו העושים במלאכת האבנים והנה יחד אוספו והמציאו לפני המלך פקדונו ולא די שלא עשו בהם מלאכת התיקון והיופי אלא עוד להם קלקלו אותם ולכלכו אותם והחזירום כשהם מקולקלים וכעס המלך על הדבר והצית אש בכל העבדים ההמה ואת בניהם הקים תחתם ויראם את אשר פרץ באבותם פרץ עז''ה ויצום ויאזרם לבל עשות כמעשה אבות, וימלך לבלתי הרבות להם המלאכה והקיל מעליהם הדבר ויתן להם שלשים אלף עד ארבעים אלף וזה היה לבחירת ההטבה לעבדיו אולי יוכלו הכין גם לצד אמצעות היות פקודת המלך קרובה יתנו לב:
@2 **הן** הנה הדברים הנאמרים במלך ישראל אלהי עולם ברוך הוא אשר חלק אבנים טובות הם הנשמות הנקראים אבנים יקרות, והוא סוד אומרו (מ''ט כ''ד) משם רועה אבן ישראל שבאמצעות הכלים וההכנה אשר הכין בידינו היא התורה ומצותיו יתברך להאיר אותם ולעשותם בתיקון אשר יאות עשות, על דרך אומרם ז''ל (זהר ח''א פב) כי באמצעות התעצמות האדם בעשות טוב וריחוק הרע על פי התורה יעשה לנשמתו מעלה עליונה ויאיר אורה מאור תורה ויכין לה כסא והוא בחינת המשבצות אשר כתבנו במשל, גם יקנה לה כתר מלכות. ולראשונים התחיל ה' להרבות להם המלאכה ונתן להם נשמות גדולות שבכל אחת יש בה חלקים רבים, והגביל לכל חלק מלאכתו יום א'. והוא סוד (שמות ט''ז ד') דבר יום ביומו כי הענף יקרא יום ונתן להם ימים רבים כנגד חלקים אשר בנפשותם, לאדם נתן יותר משלש מאות אלף חלקים שהם מספר ימיו תתק''ל וכשיעור זה הן חסר הן יתר לדורות ההמה, וכשקלקלו ופרץ ה' בהם פרץ ואת בניהם הקים תחתם נח ובניו משם והלאה הקיל ה' מתת רוב הטורח ההוא כדי שתהיה הפקידה קרובה ויתחלחלו האנשים מעת הפקידה, וכשראה כי לא יכלו לעמוד היה מחסר והולך להקל, והן היום בעונותינו ימי שנותינו בהם ע' שנה שהם בקירוב חמשה ועשרים אלף יום ורבים מבני עמינו לא עמדו בעבודה קלה כזו:
@2 **גם** בזה הרוחנו מה שאנו רואים כי כשיזקין האדם תתמעט הבנתו ואפילו איש חכם לא יוכל לצאת ולבא במלחמתה של תורה ויתמעטו הרגשותיו הגם שאמרו ז''ל (סוף קנים) זקני תורה דעתם מתיישבת עליהם, דקדקו לומר מתישבת לשלול דעתם של זקני עם הארץ שמתטרפת ולעולם כח השכליי והתבוניי יאפס. ולפי ההקדמה האיר ה' עין בדבר זה כי לצד שנסתלקו כל חלקי הנפש אין כח במועט הנשאר לעשות כשיעור הכל גם לא תעמיד הגוף ויכבד קצתו על קצתו לצד מיעוט המניק והזן שהיא הנפש וישוב כדעת קטן:
@2 **גם** בהקדמה זו הרוחנו כוונת מאמר רז''ל (ב''ר פ' ס''ב) שאמרו מה בין מיתת זקנים למיתת נערים מיתת זקנים וכו' יפה לנר ויפה לפתילה וכו' עד כאן, המשילו מיתת הזקן לנר וכשם שהנר הולך ומתמעט גם הזקן כבר הלכו להם חלקי הנפש וחלק האחרון שנשאר בו ביציאתו יהיה נדמה לו כאדם הישן שלא ירגיש ביציאת החלק ממנו והבן:
@2 **גם** בזה הרוחנו פירוש מה שאמר הכתוב (תהלים ק''ד) תוסף רוחם יגועון שאין כוונת הכתוב ידועה, גם לא אמר תוסף ברוחם, וכפי ההקדמה יאיר אור הכתוב כאור השמש שיתכוון לומר כי כשיגיע קץ האדם פקודת נפשו יתוספו בו כל חלקי הנפש שנדו והלכו מידי לילה ולילה, והוא אומרו תוסף רוחם פירוש הרוח עצמה שלהם, וכבר אמרנו שהגם שהולכת אינה נעקרת בהחלט אלא הרי היא כיציאת הנשמה בלילה בעת שינה שמאיר אורה בגוף למטה והיא למעלה וזה לך האות בהעיר אדם את הישן ירגיש חלק המתעורר וירגיש גם חלק אשר עלה והבן:
@2 **גם** הרוחנו דעת כי אותם חלקי הנשמה נקראים ימים:
@2 **ובזה** האיר משמעות הכתוב שבאנו עליו שאמר **ויקרבו ימי ישראל למות** פירוש חלקי הנשמה שעלו ממנו דבר יום ביומו הן עתה קרבו כמאמר הכתוב תוסף רוחם והוא אומרו למות, והרגיש יעקב אבינו בתוספת המרובה כי באו ימי השילום ויקרא לבנו ליוסף וגו':
@2 **ויקרא לבנו ליוסף וגו'**. טעם שלא קרא אלא ליוסף, יש טעם פשוט בדבר לפי שיש בידו יכולת. אלא צריך לדעת טעם אומרו **לבנו** ולא הספיק לומר ליוסף ואין לנו יוסף אחר לטעות. גם הוסיף תיבת למ''ד ליוסף ולא הספיק לומר לבנו יוסף. נראה כי בא הכתוב לתת טעם לקריאה איך יקרא הדיוט למלך והלא מצינו שכבוד מלכות עדיף מכבוד רבו, שנסתפקו במסכת קידושין (לג:) בבעיא בנו והוא רבו ואמר שם הש''ס כשרצה לפשוט מימרת ר' יהושע בן לוי שאמר אני איני כדאי לעמוד בפני בני אלא משום כבוד בי נשיאה, וכבר הארכתי בסוגיא זו כיד ה' הטובה עלי בחיבור ב' (ראשון לציון) שחיברתי על יו''ד בסי' ר''מ ס''ז יעש''ד, ועל כל פנים מדברי התלמוד מוכח בפירוש כי גדול חיוב כבוד בי נשיאה על אביו ואפילו לא היה בנו עצמו נשיא אלא חתניה דבי נשיאה, ואם כן איך יעשה יעקב הדבר לשלוח לקרוא למלך לבא אצלו ולזה אמר הכתוב ב' טעמים בדבר, האחד היותו בנו, והב' היותו יוסף, ובא' מהנה לא יספיק לקרותו, אם לא היה בנו הגם שיהיה צדיק וחביב וחובב אותו אין כח ביעקב לעשות כדבר הזה משום כבוד מלך, ואם היה בנו ולא היה צדיק גם כן לא היה קורא אותו, אלא לצד היותו בנו והוא אומרו **לבנו** גם להיותו יוסף הידוע בצדקות הידוע בהפלגת אהבת האב לו והוא לאביו לטעם זה הוא ששלח לקרא לו שידע שימחול על כבודו, והגם שאמרו ז''ל (קידושין לב:) מלך שמחל על כבודו אין כבודו מחול, דוקא מלך ישראל שנמשח ומלך על ישראל אבל מלך כזה במציאות זה יכול למחול על כבודו לעשות רצון אביו, גם במציאות שאין אביו יכול הלוך אליו:
@2 **אם נא מצאתי חן**. אומרו **נא** תתפרש לשון בקשה ולשון עתה, לשון בקשה לשלול המציאות חן שאינה לצד מה שקדם אליו מהחיוב ממנו. ולשון עתה נתכוין לרמוז לו כי כבר ידע יעקב כי מצא חן בעיני יוסף וזה לך האות (מ''ז י''ב) ויכלכל יוסף את אביו וגו' ומעתה אם היה אומר אליו יעקב אם מצאתי חן זה יגיד כי לא הוכר אצלו דבר זה שמצא חן בעיניו, לזה אמר עתה פירוש מה שמבקש ממנו מציאות חן הוא על מה שעתה:
@2 **או** ירצה לצד שהגיע הערב שמשו הרי זה כלה צורך החסד הרגיל עד עתה מיוסף אליו לזה אמר אליו אם עתה עדיין רוצה להתמיד בהנהגת מציאות חן שים וגו':
@2 **עוד** בדרך רמז נתכוון לרמוז לו להיות שכל החסד שעשה עמו עד עתה היה דן בו ב' צדדין, האחד שעושה לצד שמצא יעקב חן בעיניו לא לתכלית סיבה וזה יהיה מצד האהבה הנכונה ומתיחסת למציאות חן, והב' כי עשה לצד החיוב שהוא מחויב לזון אביו כדרך כל הארץ וחרפה הוא לו להטיל אביו ואחיו על הזולת ולראותם חסרי לחם ומזון, לזה אמר אליו כי הדבר שהוא בספק מה היתה כוונתו יתברר הספק במה ששואל ממנו עתה אם עתה יעשה לו חפצו ורצונו נודע הדבר למפרע כי מה שעשה עמו מהטובות הוא לצד שמצא חן בעיניו באהבה ורצון הלב כי דבר ששואל ממנו הפעם הזאת אינו דבר שיצטרך לעשותו זולת אם אהבתו נכונה ושלימה ויחפוץ להטיבו וזה הוא גילוי על העבר כי מצאתי חן בעיניך ואם לאו יתברר הדבר כי טעם החסד העובר הוא לצד הב' שכתבנו ובזה ידוייק אומרו **מצאתי** לשון עבר:
@2 **שים נא**. תתפרש לשון זמן ולשון בקשה, לשון בקשה, מלבד מה שאמר לשון בקשה בסמוך על המעשה חזר לומר בקשה פעם ב' כי מלבד שיסכים על החסד ויאמר לו לעשות כן עוד מפייסו להשבע לו על החסד לקיימו, ותתפרש לשון עתה שנתכוון לשלול ממנו תשובת עוד היום שבו יעשה דבר זה כי לא היה זמן המות כמו שתמצא שאמר אחר זה ויהי אחרי הדברים האלה וגו' הא למדת שלא היה אז בפרק הנסיעה לזה אמר אליו שים עתה מבלי טענת עד עת בוא דבר מלך שלטון, גם חש יעקב למסירת מודעה על הדבר ויקדים שבועה לבטל שבועה זו וישבע לו שבועה שאין בה סמיכות דעת, ומה גם לדבריהם ז''ל שאמרו (תנחומא) שאמר לו יעקב אם לא ישבע לו הרי הוא מת מדאגה ורמוזה באומרו ושכבתי עם וגו' אם כן יוסף לצד הכרח הדברים ישבע אחר שיקדים שבועה לשבועתו, לזה אמר אליו **שים נא** פירוש עתה תכף ומיד ומנע ממנו הזמן שבו ימסר מודעה לבטל שבועה זו:
@2 **ועשית עמדי חסד ואמת**. אמר **ועשית** בתוספת וא''ו, לצד שקדם בקשת מעשה השבועה אמר ועשית בתוספת וא''ו. ואומרו **חסד ואמת**, רז''ל אמרו (ב''ר פ' צ''ו) כי חסד העשוי עם המתים קרוי חסד של אמת. וקשה לי הלא מצינו לו ליעקב ששילם לו חסד זה שנאמר (מ''ח כ''ב) ואני נתתי לך שכם אחד וגו' ופירש''י אתה טורח בשביל קבורתי ואני נתתי וגו', גם מאומרו נתתי לשון עבר יגיד כי הודיעו הדבר בשעת מעשה כשקבל עליו הטורח, והגם שלא נאמר כן, יעקב מיהא היה בדעתו להטיבו שכר טורחו ולא היה לו לומר ואמת:
@2 **ואולי** כי נתכוון כי יוסף יעשה הדבר כדרך זה:
@2 **ועשית עמדי חסד ואמת**. אמר ועשית בתוספת ו', לצד שקדם בקשת מעשה השבועה אמר ועשית בתופת ו'. ואומרו חסד ואמת, רז''ל אמרו (ב''ר פ' צ''ו) כי חסד העשוי עם המתים קרוי חסד של אמת. וקשה לי הלא מצינו לו ליעקב ששילם לו חסד זה שנאמר (מ''ח כ''ב) ואני נתתי לך שכם אחד וגו' ופירש''י אתה טורח בשביל קבורתי ואני נתתי וגומר, גם מאומרו נתתי לשון עבר יגיד כי הודיעו הדבר בשעת מעשה כשקבל עליו הטורח, והגם שלא נאמר כן, יעקב מיהא היה בדעתו להטיבו שכר טורחו ולא היה לו לומר ואמת:
@2 **ואולי** כי נתכוון כי יוסף יעשה הדבר בדרך זה:
@2 **או** אפשר כי בערך המעשה לא יוכר הפרעון שתנתן לו שכם אחד:
@2 **או** לצד שבקש ממנו ב' דברים האחת שלא יקברנו במצרים וישתדל בהוצאתו מעיר גילולים, והב' שיעלה הוא ויקברהו בארץ כנען, ואמר חסד של אמת על בחינת העליה מארץ מצרים, והוא שאמר סמוך לאומרו **חסד ואמת אלנא תקברני במצרים** והנה מהראוי לו להקדים השכיבה ואח''כ הקבורה וכאן הקדים להזכיר הקבורה קודם אומרו ושכבתי, אלא הרי זה מראה באצבע כי על פרט זה היא ההשבעה ודבר זה אין לו פרעון לא עתה ולא אחר זמן. ומה שנתן לו שכם אחד הוא על הטורח שיעלה עמו מארץ מצרים לארץ כנען ויקברהו שם:
@2 **עוד** יתבאר הכתוב על זה הדרך **ועשית** וגו' פירוש מה שכבר עשית עמדי יהיה של אמת פירוש חסד הגמול, כי מה שנותן לו שכם הוא למה שעתיד לעשות לטרוח בקבורתו לא לתגמול העובר, ובזה ידוייק גם כן תיבת ועשית בתוספת וא''ו גם לשון עבר, תוספת וא''ו שיוסיף להטיב עמו במה שיחשוב החסד שכבר עשה שהוא של אמת ולא יקבל הטבה ממנו בעדו ובזה תהיה ההטבה הבאה מושלמת מהמשביע והוא נשבע על דעת חבירו בשביל טובה שעשה לו שאין לו התרה (ר''ן נדרים סה) ונתחכם יעקב לבל יתיר יוסף השבועה אחר מותו, והגם שלא מצינו שהזכיר יעקב ההטבה של שכם אחד אז, הכתוב גילה במקום אחר שהזכירה לו כבר דכתיב נתתי לך ומן הסתם מקום זכרונה הוא כשאמר לו השבעה לי לחזק השבועה לבל יתיר נתן לו שכם אחד, וזולת זה במה יסמוך דעתו של יעקב בשבועה זו כיון שיכול להתיר אחר כך וכמו שהארכנו בפרט זה בפרשת תולדות (כ''ו כ''ו) בשבועת יצחק לאבימלך. ומה שאמרו ז''ל (סוטה לו:) שאמר יוסף לפרעה אם אני מתיר שבועת אבי אתיר גם כן שבועתך אין סתירה מזה, או לצד שלדבריו של פרעה השיבו, או גם שבועתו לפרעה היתה בשביל טובה שעשה לו שאין טובה כמותה גדולה וכבוד ועושר:
@2 **אל נא תקברני וגו'**. פירוש אל נא לשון זמן שאפילו לפי שעה לא יקברוהו על סמך שישתדל אחר כך להעלותו אלא תיכף ומיד יעלהו, והוא אומרו בסמוך **ושכבתי** וגו' **ונשאתני** וגו'. וטעם הקדמת אל נא תקברני במצרים לאומרו ושכבתי פירשתי בפסוק ועשית עמדי וגו' לא' מהדרכים שישבתי הכתוב. ולשאר הדרכים יתבאר לפי מה שקדם לנו (זהר וישב קפ''ב) כי יעקב ויוסף היו בחינת נפש אחת והוא סוד וא''ו מליאה שיש לה ב' ווי''ן ולא יתפרדו, ואשר על כן חש יעקב שאחר שיאסף לא יתרצה יוסף להפרד ממנו גם במותו, ומה גם לדבריהם ז''ל (תענית ה:) שאמרו יעקב אבינו לא מת והוא בחיים, לזה שלל דבר זה מדעתו והודיעו כי כשישכב פירוש כשיפטר הנה הוא נפרד בהכרח ממנו ויסמך עם אבותיו ולזה ונשאתני וגו' וקברתני וגו':
@3 **ויאמר אנכי אעשה וגו'**. צריך לדעת למה הוצרך לומר לו כן והיה לו לעשות המעשה בפועל וזאת היא תשובתו, וכמו שמצינו גם כן לאליעזר עבד אברהם כשאמר לו אברהם (כ''ד ב') שים נא ידך וגו' התשובה היתה וישם העבד את ידו וגו':
@3 **אכן** הכונה היא שאמר לו תשובה שאינו צריך לישבע לו והנה הוא מוכן לעשות כדבריו:
@3 **או** ירצה שכפי הדין הוא מחוייב לעשות כדבריו או לצד שהוא בנו והוא אומרו **אנכי אעשה**, או לצד שהוא מצוה מחמת מיתה (חו''מ רנב) והוא אומרו **כדבריך** ואינו צריך שבועה, ובזה הודיע יוסף ע''ה צדקתו כי חפץ חסד הוא לעשות דבר מצוה מרצונו הפשוט:
@4 **ויאמר השבעה לי**. הוצרך לומר לו פעם ב' השבעה ולא הספיק במה שענהו לעשות כדבריו, לפי מה שפירשנו בפסוק אנכי אעשה וגו'. יבא על נכון כי משיבו למה שאמר שאינו צריך שבועה כי מצדיק הוא דבריו אלא לעשות רצונו הוא מבקש ממנו לישבע, והוא אומרו **השבעה לי** פירוש להפיס דעתי, או לטעם הכמוס עמי, והכוונה חושש לזולת שיהיה מונע אותו, וכמו שכן היה שאמר לו פרעה שיתיר שבועתו כאומרם ז''ל, (סוטה לד:) ולזה תכף נשבע לו:
@4 **או** יאמר **השבעה לי** לדעתי כדי שלא יבטל השבועה בלבו ועיקר השבועה בלב, ועשה יעקב כן לבטחון לכל צדדי הספק שיהיו בדבר:
@5 **שני בניו עמו את וגו'**. טעם שלא הספיק באומרו שני בניו ואני יודע כי הם מנשה ואפרים, או לומר מנשה ואפרים ואני יודע כי הם בניו הרשומים בפרשת מקץ, גם הפסיק בין הזכרת הבנים והודעת שמם בתיבת עמו, גם אומרו את ב' פעמים. אולי כי יודיע הכתוב טעם יוסף בלקיחתם שהיתה לקחת כל אחד ברכתו בפני עצמו מלבד מה שיגיע אותם בברכת אביהם, והוא אומרו **את שני בניו עמו** זה מה שנוגע לחלק שיהיה נוגע להם בברכתו, גם את מנשה שיבורך בפני עצמו, ואת אפרים וגו':
@5 **או** ירצה כי ראויים הם לברכה מב' צדדין לצד שהם בניו ולצד שכל אחד מהם ראוי לברכה מצד עצמו, ולזה אמר **בניו עמו** גם לצד היותם מנשה ואפרים צדיקים, ואמר עמו להפסיק שלא תבין שמפרש מי הם הבנים, ואמר את ואת לומר שכל א' חשוב בפני עצמו:
@8 **הנני מפרך וגו'**. כפל לומר מפרך והרביתיך כנגד ב' בנים שיהיו לו עוד כמו שפירש הדברים יעקב באומרו ועתה. ואומרו **ונתתיך לקהל עמים** פירוש שיהיו ב' הבנים כל אחד לקהל ועם:
@9 **ועתה שני בניך וגו'**. פירוש עתה שראיתי שלא היו לי בנים עוד מצד אותה ברכה אני יודע למפרע כי ב' בניך הנולדים לך וגו' לי הם שאמר לי ה' מפרך והרביתיך והוא שאמר לו ה' בבית אל (ל''ה י''א) פרה ורבה כראובן ושמעון יהיו לי, ועיין מה שכתבתי בסמוך:
@10 **ומולדתך אשר וגו'**. פירוש שלא ימנה יוסף במקום ג' שבטים אלא במקום ב'. וכפי זה לא יקרא עוד שבט יוסף במנין השבטים זולת שבט אפרים ושבט מנשה, וכמו כן מצינו שכן הוא:
@10 **ויש** לנו לחקור זאת למה הוציא יעקב את יוסף ממנין השבטים כמו שמצינו שלא נמנה בכלל השבטים כי אם אפרים ומנשה ולמה לא ימנה הוא גם כן ויהיו י''ד שבטים עם לוי כי ה' אמר אליו שיהיו ממנו ב' שבטים נוספים לא שיעקר שם יוסף. גם צריך לדעת מי אמר ליעקב כי ב' הגוים שאמר לו ה' שיהיו ממנו הם בני יוסף ולא בני שאר בניו ויותר היה לו לתלות ולומר שהם פרץ וזרח שהם ביותר מעולים כפי האמת שהם שלשלת המלוכה. ואולי כי בני יהודה נרמזו במה שאמר לו עוד שם ה' ומלכים מחלציך יצאו. אלא מי יאמר שכוונת ה' באומרו ומלכים מחלציך וגו' היא זאת. ועוד אחרת דלמא הם הם גוי וקהל גוים הם הם המלכים. ועוד מי יאמר שאין הדברים נאמרים על בני שאר האחים:
@10 **אכן** במה שנשכיל על דבר הבורא שאמר אליו בנבואה גוי וקהל גוים יהיה ממך ומלכים מחלציך יצאו פשט הדברים יגיד שעל יעקב הוא אומר שממנו יצאו לא מבניו:
@10 **אלא** יש לדעת מאמרם ז''ל (זהד ח''א ק''פ) כי יוסף הוא בחינת נפש יעקב. והוא שרמז הכתוב באומרו (ל''ז ב') אלה תולדות יעקב יוסף. והוא אומרו (תהלים עז) בני יעקב ויוסף, ורמזו חכמי אמת כי הוא בחינת מילוי הוא''ו שהמילוי כאות עצמו. ועל פי הקדמה זו יתיישבו כל הדקדוקים, כי יוסף הוא בחינת יעקב ובמדרגת אב לשבטים יקרא כרשום גם כן באומרו בני יעקב ויוסף, וכפי זה כשאמר ה' ליעקב שיצאו ממנו עוד בנים זה יעקב זה יוסף ולזה לא הלביש הנבואה בשאר בניו, ולזה דקדק לומר ב' בניך וגו' לי הם פירוש במדרגת בני יעקב לא במדרגת בני בניו ולזה הוסיף לבאר ואמר כראובן ושמעון, ומעתה הרי יוסף במדרגת אב כיעקב ואין האב נמנה עם הבנים בגדר אחד כמו שאין יעקב נמנה עם השבטים:
@11 **ואני בבואי מפדן וגו'**. כתוב זה אין **לו** קשר עם מה שלמעלה ממנו. גם אין ידוע כוונת הודעה זו. ומה שפירשו ז''ל (רש''י לקח טוב) כי כונתו היא אף על פי שהטרחתיך להוליכני ליקבר בארץ כנען ולא כך עשיתי וכו' עד כאן. לפי דבריהם לא כאן הוא מקום הדברים אלא למעלה (מ''ז ל') כשאמר לו ונשאתני ממצרים וקברתני וגו', סמוך לזה היה לו לומר ואני בבואי וגו'. עוד מה כוונתו באומרו תיבת **עלי**:
@11 **אכן** לפי מה שפירשתי כי מודיעו שהבנים המובטח בהם שיצאו ממנו הם אלו נתכוון באומרו **ואני בבואי** וגו' כי הוא סיבה שלא יצאו ממנו ממש לצד שהוא גרם שתמות רחל, והוא אומרו **מתה עלי** פירוש על סיבתי כאומרם ז''ל, (ויק''ר פ' ל''ז) ששהה נדרו או לצד הקללה שקלל כאומרו עם אשר תמצא את אלהיך לא יחיה ואלו היתה קיימת רחל היו יוצאים ממנו ועכשיו יצאו מיוסף שהוא בחינת יעקב גם בחינת רחל:
@11 **עוד** אפשר שנתכוון יעקב לרצות את יוסף על אשר סיבב מיתת אמו קודם זמנה ואמר כי טעם אשר החשיב ב' בניו כראובן ושמעון לצד כי מתה עליו רחל וקרב מיתתה, וטעם מה שהאריך לומר עוד **בעוד כברת ארץ** וגו' נתכוון **לומר** מה שדרשו ז''ל שנתכוין לומר אף על פי שלא כן עשה לאמו וכו':
@12 **וירא ישראל וגו'**. קשה והלא י''ז שנה היו יושבים לפניו ללמוד תורה ואיך שואל עליהם, ורז''ל אמרו (תנחומא) כי ראה בהם ראייה שכליית שעתיד לצאת מהם רשעים, וזה דרך דרש, וצריך לפרש הכתוב כפי פשוטו. והוא כי גילה לנו הכתוב שיעקב כבדו עיניו מזוקן שלא היה יכול לראות ולהכיר, ולצד זה הגם שראה ב' בני אדם עומדים לפניו לבד יוסף שעמו היה מדבר והכירו לצד שהודיעוהו שאמרו לו (ב') הנה בנך יוסף כאמור למעלה והבנים לא הכירם לזה שאול שאל עליהם מי אלה:
@12 **עוד** אפשר שנתכוון יעקב לעורר אהבת האב על הבן קודם שיברכם כדי שתהיה הברכה בתגבורת האהבה והחיבה, ולזה שאל **מי אלה** כדי שישמע מפי בנו החביב אצלו לומר בני הם ויהמו מעיו להם, והוא סוד (ירמי' לא) מדי דברי בו וגו' רחם ארחמנו וגו':
@13 **אשר נתן לי וגו'**. דרך הצדיקים כשזוכרים הטוב אשר הגיעם חולקים כבוד לה' כי הוא הנותן, כאומרו (ל''ג ה') הילדים אשר חנן אלהים וגו':
@13 **ואומרו בזה** כפי הפשט כי אפילו בימי גלותו בארץ נכריה חננו ה'. גם רמז למאמרם ז''ל (סוטה לו:) כי עתיד היה יוסף להוליד י''ב שבטים ועל ידי מעשה אשת פוטיפר נרזבו מבין צפורני ידיו י' טיפות ולא נשארו אלא ב', והוא שרמז באומרו **בזה** זה בגימטריא י''ב במקום י''ב נתן לו אלהים ב'. ודקדק לומר **אלהים** שיורה על המשפט:
@14 **ועיני ישראל וגו'**. צריך לדעת למה כתיב הודעה זו במקום זה, ומה קשר ושייכות לדבר זה עם הסמוך לו וישק להם ויחבק להם. עוד צריך לדעת אומרו **להם** שהיה לו לומר וישק אותם. ואולי ששני דקדוקים אלו כל אחת מתרצת חברתה כי לצד שכבדו עיניו מזוקן היה מחבק שלא במקום החיבוק ומנשק שלא במקום הנישוק ולזה אמר להם ולא אמר אותם והבן:
@18 **שכל את ידיו כי וגו'**. אמר תיבת כי והוא טעם להפך, יש שפירשו על זה הדרך כי מנשה הבכור ואף על פי כן וגו':
@18 **והנכון** בעיני הוא לפי מה שקדם הכתוב להודיע כי עיני ישראל כבדו מזוקן לא יוכל הכר מי הוא הבכור ומי הוא הצעיר, לזה כשרצה לברך דן בדעתו כי המסדר יסדרם בדרך מוסרי לעשות הבכור לימינו של המברך ובזה ידע מקום כל אחד מהם ועשה מה שעלה על מחשבתו עשות, וזה הוא שיעור הכתוב שכל את ידיו וא''ת מנין ידע והכיר מקומו של כל אחד לזה אמר כי מנשה הבכור ומזה ידע כי אותו יהיה לימין ולזה שכל ידיו:
@19 **ויברך את יוסף**. לא ראינו ברכה ליוסף כאן. ורמב''ן פי' כי ברכת הבנים היא ברכת יוסף וכו'. ואין הדעת נוחה בזה כי למה לא יתברך יוסף עצמו בדברים הנוגעים אליו בפרטות. והנכון בעיני כי בתיבת ויברך רשם הכתוב כי בירך ליוסף שיהיה תמיד מבורך:
@19 **עוד** יתבאר על פי דבריהם שאמרו (ב''ר פ' ל''ט) שמפתח הברכות היה ביד אברהם ומסרו ליצחק ויצחק מסרו ליעקב (שם פ' ס''א) ויעקב מסרו ליוסף, והוא אומרו **ויברך** וגו' פירוש מסר בידו מפתח הברכות:
@19 **ויאמר האלהים וגו'**. התחיל לעורר האהבה של הקדמונים כסדר תפלת י''ח שמתפללין שמתחילין בזכרון אבות ואמר האלהים אשר וגו' אברהם ויצחק והזכיר גם כן זכותו בהצנע ואמר האלהים הרועה אותי וכאן רמז זכותו על זה הדרך כי הוא יעקב היה מתהלך לרצונו יתברך כשה לפני רועה הרועה אותה, ואחר שסדר זכות אבות התחיל להתפלל המלאך וגו':
@20 **המלאך הגואל וגו'**. פירוש מאמר ה' אשר יצו ה' את ידידיו אליו יקרא שם מלאך כי קול ה' חוצב להבות אש. והוא כוונתו באומרו המלאך וגו' פירוש שיהיה מימרא דה' בסעדם ויברך אותם:
@20 **ויקרא בהם שמי וגו'**. פירוש שיהיו בהדרגת שלשה אבות וכשם שאין אדם בעולם יכול לנתק או לקלקל באחד מג' אבות ואין צריך לומר בכולן יחד כמו כן הם:
@20 **עוד** ירצה לשון יקר וגדולה פירוש שיגיע באמצעותם יקר לשם אבות, והוא על דרך אומרו (משלי כג) גיל יגיל אבי צדיק וכן הוא אומר (שם י''ז) עטרת זקנים בני בנים, וזה יהיה באמצעות הכנתם ההגונה ודרכם הישר עד שיגיע יקר לאבות אבותם:
@20 **עוד** ירמוז כי יהיה להם חיבוב הזכרת שמם לפני ה' כחיבוב הזכרת שם אברהם יצחק ויעקב, וכמו כן תמצא שאמר הנביא (ירמי' לא) הבן יקיר לי אפרים וגו' כי מדי דברי בו וגו', הרי כי שמו של אפרים נתייקר בעיני ה' ומזכירו בחשק וחבה יתירה:
@20 **וידגו לרוב וגו'**. הכוונה על דרך מה שפירשתי בפ' בראשית בפסוק (א' כ''ב) ויברך אותם וגו' האמור בדגים כי הוצרך ה' לברכם לצד שמקום דירתם הוא נגדיי בקצה האחרון לבחינת הלידה לזה הגדיל בהם כח המוליד להוליד אפילו במים, וכאן אמר יעקב שידגו כדגים בריבוי הלידה ויהיה להם גדר זה בארץ, וכפי זה תהיה ברכתם גדולה מברכת הדגים להיותם במים והבן. ודקדק לומר **בקרב** רמז שיהיו נחבאים בפנים על דרך מה שאמר להם יהושע (סוטה לו:) בזמן שנתקיימה ברכת יעקב בהם לכו החביאו עצמיכם ביערים, כי יהושע פירש הכתוב כפירושינו. ויש דרשה בזה (ברכות נה:) שהמשילם לדגים שאין עין הרע שולטת בהם, וכפי זה אומרו **בקרב הארץ** פירוש הגם שיהיו בקרב הארץ, ובזה הם בגדר עליון מהדגים:
@22 **ויאמר יוסף וגו' לא כן אבי**. טעם שהאריך כל אלה הדברים לא כן אבי כי זה הבכור וחזר עוד לומר שים ימינך וגו':
@22 **הנה** נסתפק יוסף באחד מב' דרכים, הא' הוא שחשב יעקב כי הבנים היו לקוחים ביד יוסף בשעת ברכה וידוע הרבר כי יקח בימיגו הבכור ובשמאלו הצעיר וכפי זה יהיו לפני יעקב הבכור לשמאלו והצעיר לימינו, ואשר על כן שכל את ידיו כי מנשה הבכור ואותו ישים אביו ביד ימינו, ודרך ב' שבכונת המכוון שכל את ידיו לשום ימינו על ראש הצעיר, לזה אמר לו בתחלה אם כונתו היא לחושבו כי לקחם אביהם בידו הבכור לימינו של יוסף אמר **לא כן אבי** כמו שאתה חושב כי זה הבכור, ואם אתה יודע כי סדורים הבכור לימינך וגו' אלא שאתה מונע ימינך מהבכור לזה אמר **שים ימינך על ראשו** פירוש למה תמנע הטובה מבעליה, וכבר ידעת מה שגרם דבר זה:
@23 **וימאן אביו ויאמר ידעתי וגו'**. אומרו **וימאן**, לצד שהיה רוצה לסמוך יד אביו להסיר אותה, וכפל לומר **ידעתיבני ידעתי**, נתכוון להשיבו לב' דברים שאמר כמו שפירשנו, כנגד מה שאמרת לא כן אבי כי זה הבכור ולא כמו שאני חושב שסדורים בהפך ידעתי בני ורמז באומרו בני פירוש ומן הסתם לא תחשיב ימינך לפני ימיני ולא תסדרם אלא הבכור לימיני ולא לימינך, וכנגד מה שהורתני לעשות משפט הבכורה באומרך שים ימינך על ראשו ידעתי גם זה ובכלל ידיעה זו נכנסה גם ידיעת המסובב מדבר זה בעשות כן ליוסף, ואמר **גם הוא יגדל** פירוש לא תחשוב שהוא במדרגה שפלה אלא יגדל ויהיה לעם, ואולם וגו' פירוש לא לצד ברכתי אלא לצד מה שיצא ממנו **וזרעו יהיה מלא הגוים**, לזה הגם שבזמן זה זה הבכור לעתיד יהיה הקטן יותר גדול כאומרם ז''ל (תנחומא) שזה יצא ממנו גדעון וזה יצא ממנו יהושע ומן הסתם שלשלת זו היתה בשורש נשמת השבט מבלי ברכת יעקב ואשר על כן אני מקדימו לבכור:
@23 **או** ירצה על זה הדרך ידעתי כל טענותיך, ומה שרמזת כי זה גורם לא זה גורם אלא בני פירוש בני הוא שגרם לכל העובר בחלומותיך ודבריך. ואומרו **ידעתי** פעם ב' נמשכת עם למטה ממנה גם הוא וגו' ואולם וגו' פירוש שידע בנבואה שהקטן יגדל מהגדול ואינו יכול לעשות הפך מהחזון אשר דימה כידו האדון ברוך הוא:
@24 **ויברכם ביום ההוא לאמר וגו'**. פירוש בירך אותם כל כך ברכות עד גדר שאין ברכה למעלה ממנה עד שהכל אומרים בך ראוי לברך ישראל. ואומרו **וישם את אפרים** וגו' פירוש באמצעות דיבור זה קבע מקום למעלה לצעיר קודם למנשה כי מי הוא זה מבני ישראל אשר ישנה מטבע יעקב אבינו ויאמר לבנו ישימך אלהים כמנשה וכאפרים והיה מאמר זה לאות כי אפרים קודם מנשה לכל דבר:
@25 **ויאמר ישראל וגו' והיה אלהים וגו'**. כוונת אומרו **אנכי מת** וגו' פירוש שלא יחשבו כי במות יעקב תסתלק השכינה מביניהם אלא אפילו ימות יהיה אלהים עמהם. ואומרו **והשיב** וגו' הודיעו שיהיו נפקדים לשוב שבותם באין ספק בדבר, ודקדק לומר **ארץ אבותיכם** כי הארץ לאבות נתנה והם זכו בה לא ליוצאי מצרים ומעתה יש בידי לתת לך שכם אחד וגו' כי בזה תוצדק הנתינה ממנו אליו, והוא אומרו **ואני נתתי לך** וגו'. וגם לדברי רז''ל (ב''ר פ' צ''ג) כי שכם זו כמשמעה שבאו בני יעקב על חלליה, על אף פי כן זולת זכות אבות בארץ לא יזכה בה יעקב ולא בניו:
@29 **ראובן בכורי אתה וגו'**. יש להעיר מה חידוש מודיע יעקב לראובן כי הוא הבכור:
@29 **עוד** אומרו **כחי וראשית אוני** מה הוא דעתו בזה, ורז''ל אמרו (ב''ר פ' צ''ח) כי הודיעו בזה כי הוא טיפה ראשונה, ועדיין צריך לדעת מה היא כוונת הודעה זו לראובן:
@29 **עוד** למה כפל לומר כחי ולא הספיק לומר ראשית אוני:
@29 **עוד** צריך לדעת כוונת אומרו **יתר שאת ויתר עז**. ורז''ל (שם) אמרו שאת זה כהונה עז זה מלכות וכו', וצריך לדעת למה לא אמר חלק פי שנים אחר שירד לפרט פרטי המושג לבן בכור. ואונקלוס הוסיף להזכירה בתרגומו ואמר תלת חולקין וכו':
@29 **עוד** צריך לדעת כוונת אומרו **פחז כמים אל תותר**. ורש''י ז''ל פירוש על אשר פחזת כמים לזה אל תותר לא יהיה לך היתירות ומה הוא הפחז כי עלית משכבי וגו'. ועדיין צריכין אנו למודעי למה לא הספיק לומר אל תותר כי עלית אחר שהפחזות הוא כינוי לעון היה לו להזכיר העון לבד ומה לי עשאו בחפזון או שלא בחפזון:
@29 **עוד** למה הפסיק בעונש באמצע הודעת העון שהיה לו לומר על זה הדרך אל תותר פחז כמים כי עלית או על זה הדרך פחז כמים כי עלית וגו' אל תותר:
@29 **עוד** צריך לדעת כוונת אומרו **עלית משכבי אביך** לשון רבים:
@29 **עוד** מה כוונת אומרו **אז חללת** כי משמע שעשה ב' דברים בזמנים מחולקים ולזה אמר אז וגו' פירוש כי לצד שהחילול היה בזמן נפרד מזמן שעלה יצועי אביו לזה אמר אז חללת וצריך לדעת מה היא החילול שעשה זולת עלית משכבי וגו', ואם הכונה היא שבאמצעות עליתו חלל וגו' היה לו לומר עלית וגו'. חללת וגו'. והדבר מובן שאז בעלותו חלל יצועי ולא היה צריך לומר אז:
@29 **וקודם** לבא לביאור הכתובים יש לנו לחקור חקירה אחת והיא איך עשה יעקב הפך מה שכתוב בתורה (תצא כ''א ט''ז) לא יוכל לבכר את בן האהובה על פני בן השנואה הבכור והוא בכר יוסף בן רחל האהובה אצלו על פני ראובן בן לאה השנואה. וקודם צריך לתת לב אם האבות היה עליהם חיוב קיום כל התורה כי הלא מצינו שיעקב נשא ב' אחיות ואברהם לא מל עד שהיה זקן וכן כמה פרטים:
@29 **ומעתה** מה מקום לקושיא זו שבכר בן האהובה תהיה זו כערלה של אברהם קודם שנצטווה וכנשיאת ב' אחיות ליעקב. וראיתי לרמב''ן (תולדות כ''ו ה') שנתן טעם ליעקב שנשא ב' אחיות כי לא היה בארץ עד כאן, ואין דבריו חזקים בסמוכות כי מי גילה לו סוד זה שלא היה שומר תורה אלא בארץ אחר שאין הפרש בין הארץ לח''ל באותן פרטי המצות שלא שמרום האבות:
@29 **והנכון** בעיני הוא כי האבות קבלו התורה משם שקבל מנח שקבל מחנוך שקבל מאדם הראשון. אשר למדה מפי הגבורה דכתיב אז ראה וגו' ויאמר לאדם, (זהר ח''א קצט.) ושבאמצעותה צוהו לעבוד גן עדן וכמו שפירשתי בפסוק (לעיל ב' ט''ו) לעבדה ולשמרה. אך לא נצטוה אלא על ז' מצות שאם יעבור עליהם יהרג אבל שאר התורה קרוב לשכר אם יעשה ורחוק מן ההפסד אם לא יקיים, וכדרך שיש לנו גם אחר נתינת התורה שיש מצות שאם יעשה אותם האדם יטול שכר ואם לאו אין לו עונש עליהם כמו כן היה מיום ברא אלהים אדם בכל התורה חוץ מז' מצות, והאבות לצד חביבותם בה' וחשקם באושר עליון קיימו הכל כאומרו (כ''ו ה') עקב אשר שמע וגו', ואמרו ז''ל (יומא כח:) קיים אברהם אבינו אפילו עירובי תבשילין ואת בניו הקים תחתיו להרויח תועלת המצוות ועסק התורה, אבל במקום שהיו רואים תועלת דבר ההצלחה להם כמו שתאמר יעקב כשהרגיש בהצלחתו בנישואי שתי האחיות העלים עין מריוח הנמשך מקיום המצוה ההוא כיון שאין לו עונש אם לא יקיימנה כל עוד שלא נתנה תורה, ומה גם אם נאמר שהיו עושים על פי הדיבור כי האבות נביאים היו וה' אמר להם לעשות כן, ודבר זה דומה למה שכתב רמב''ם בהלכות יסודי התורה (פ''ט) כי נביא שאמר לעבור על איסור מאיסורי התורה לפי שעה שומעין לו כאליהו בהר הכרמל וגו' גם יאמן יעקב שעשה מעשה על פי נבואתו שיכול לישא ב' אחיות לפי שעה לא שיעקר איסור ב' אחיות, ומה גם בזמן שלא היה להם עונש על הדבר אלא הקרבת התועלת אם יקיימו כנזכר, גם יהודה על ידי מלאך הורשה לקחת תמר כאומרם ז''ל (ב''ר פ' פ''ד) למה שנמשך ממנה מהאצלת נשמות הקדושות, ולפי זה נאמר כי יעקב נראה בעיניו להעניש ראובן על אשר חלל יצועו ונטל ממנו הבכורה או שכן נאמר לו בנבואה, וכמו שכן אמר הכתוב בדברי הימים (א' ה') ראובן בכור ישראל כי הוא הבכור ובחללו יצועי אביו נתנה בכורתו לבני יוסף. ועדיין אין הדבר מספיק כי למה לא ניתנה אלא ליוסף ולא ליהודה או לשאר אחים הגדולים, ובס' הזוהר פ' וישלח דף קע''ו כתב טעם הדבר וז''ל בשעתא דעאל לגבה דלאה כל ההוא ליליא רעותיה ולביה הוה ברחל דחשיב דרחל איהי וכו' אהדר עובדא לאתריה וכו' בכורתיה אהדרת ליוסף וכו' ע''כ. הנה טעם זה מספיק לנטילת בכורה מראובן ותעמוד ביוסף כי הוא כפי האמת שעלה במחשבה ראשונה בביאה ראשונה כשהטיל זרעו יעקב חשב באמו. אלא קשה למה הוצרך הכתוב לומר ובחללו יצועי אביו וגו' הלא אפילו אם לא היה ראובן מחלל יצועי אביו הבכורה ליוסף נוגעת כנזכר:
@29 **וליישב** הענין דבר ידוע היא כי כל רוחניות שבעולם מתחלק לג' בחינות, אחד קדושה, ואחד חול, ואחד חלק רע, וכל אחת מהשלשה תוציא ענפיה והתאוה לבחינתה. חלק הקדושה יפריח ענפי הטוב והאושר הנצחי ותתאוה למושכלות, חלק החול יתאוה לאכול הערב לפה והנחמד לעין ויבנה בתי אבנים ועפר ויכונן מלבושים והכנות נדמים, חלק הרע יתאוה לכל תיעוב ויעשה כל אשר שנא ה' ויבחר לגזול ולרמות ולשקר ולאכול חלק הטמא נבילות וטריפות שקצים וכו' ויערב לנפשו לחבק בשר טמא נדה גויה אשת איש וזכר המרוחקים מבחינת הקדושה, ומג' אלה ישנו כל הווה וכל נמצא בין מחלקי הטוב והטהרה בין בחלקי הממוצע והוא שאנו קוראים חול בין בחלקי הרע והטומאה, וצוה ה' לעם ישראל כי לצד שהם בחינת הקדושה לבל יטעמו מחלק הרע לא במאכל ולא במשתה ולא בדיבור ולא במחשבה ולא בראיה ולא בשמיעה ולא בריח. מאכל לבל יאכל בעלי חיים טמאים וטריפות ונבילות ושקצים וכו' ולא ישתה יין נסך ויין ערלה וכדומה. דיבור שלא ידבר שקר ורכילות ונבלות הפה ולשון הרע וכדומה. מחשבה לבל יחשוב בע''ז ולא בזנות ולא יתגאה בדעתו ולא יחרוש און. ראיה לבל יביט ביופי אשה האסורה כאומרו אל תפנו אל האלילים וגו' (זהר קדושים פג:) ולא יביט בדברים האסורים לראות. שמיעה שלא ישמע דברים המשקצים ולא קול אשה האסורה וכדומה. ריח שלא יריח ריח דברים האסורים וכנגד כל בחינה ובחינה יש חלק החול וחלק הקדושה, וגזר ה' שיהיה חלק הקדושה מצוה לעשות כן וחלק החול רשות ובעת אשר ידבק האדם בבחינה אחת מהם כמו כן תדבק נפשו בשורש ההוא אם לטוב אם להפכו, ומעתה הגם שתהיה נפש אדם טהורה זכה וברה באמצעות אשר יכנים לפנימיותו מחלק הרע תהיה הנפש ההיא מעורבת מב' בחינות טוב ורע וזה יסובב לנפש ההיא טעימת המר להתייסר או גוף ונפש בעולם הזה או נפש לבד לאחר מותו, והוא סוד הכביסה שאמרו בשלהי שבת (קנב:) ינתנו לכובם. ויש לך לדעת כי כפי בחינת הרעה שנדבקה בנפש מהרע כמו כן תתאוה נפשו, כמו שתאמר אם נפשו נחלאה מטומאת הניאוף תתאוה נפשו לבחינה זו כפי מה שהקדמנו כי כל בחינה תתאוה לכיוצא בה וכי ירבה האדם להלעיט נפשו מחלקי הרע תגדל בה חשק הרע ויבדל ויתרחק מבחינת הטוב, תקח כלל זה בידך כי אין לך דבר מעשה בעולם ולא נדנוד דבר שאין לו יסוד ברוחניות, וכל דבר איסור שהודיע ה' כי הוא זה אסור כל הנדבק בו הרי הוא מושך לנפשו חלק רע, וצא ולמד מה שכתב בספר הישר (שער ט') שחיבר ר''ת בהבחנת הנפש לדעת אדם נפשו מה טיבה. ותמצא שיש אדם שאין נפשו משיחתו עשות ניאוף ויש נפש אדם שמשיחתו על הדבר ודבר זה גורם אם הוא דבק בנפשו מבחינת הרע אותה בחינה אינה יכולה להפך טבעה הרע לשנוא כיוצא בו, והוא גם כן סוד אומרם ז''ל (סוכה נב:) אבר קטן יש באדם משביעו רעב מרעיבו שבע:
@29 **גם** יש לגלות הבחנה אחת בזה כי יש אדם כי יולד יהיה טבעו להוט אחר עשות רע ויגדל עשות רשע, ויש אדם טבעו בלא שום טורח יחדל מבחינת הרע ובנקל יחזור לאחור אם יחפוץ, דבר זה ימשך מההרכבה בשעת זריעה אם נפש אדם הזורעת חושבת בחשק המעשה לצד המעשה כי יערב לו, ואין צריך לומר אם יתן עינו בכוס אחר או יחשוב במחשבות שלא במינו הטהור וצא ולמד מבני חזקיה ע''ה (עין יעקב ברכות י:) שיצאו ב' עובדי ע''ז לצד מחשבת המוליד בעממים כי המחשבה באותו מצב בונה הבנין בנולד, וזה לך עיקר גדול כי המזריעים הם הבונים לנפש הנולד, ואם תזרע בנקיון וטוהר קדיש משמיא נחית, ואם תולד בו כל שהוא מחלק הרע דרך שם תכנס בחינת הרע ותעל צחנתו ובאשו, זה הכלל לא יתאוה לבחינת הרע אלא מינו וכל שאין בו מין רע כל עיקר לא תתאוה לדבר, ואם לקחך אדם לומר והרי אדם מושלל מחלק הרע היה ואיך חטא ועבר על דברי ה'. אמור לו שוגג היה גם לא בחינת הרע גמור היה עץ הדעת והראיה כי נטוע בגן אלהים מקום שאין רע, גם אמרו ז''ל (ב''ר פ' כ''א) שאם היה ממתין עד ערב שבת קודש היה מקדש על גפן למ''ד (סנהדרין ע.) גפן היה, הא למדת שלא היה בחינת הרע אלא כדבר חול בערך קודש והוא סוד:
@29 **וא''ת** איך אברהם ילד ישמעאל ויצחק עשו, יש לך לדעת כי הם חלקי הרע שזרע בהם האב תרח אבי אברהם עובד ע''ז היה וכשיצתה נפש אברהם יצאה דבוקה מבחינת הרע אלא שגבר עליו חסד אברהם וכפה בחינת הרע עד שהפרידה ומסרה בישמעאל, ועדיין היה ניצוצי הרע דבקים עד שבא יצחק והפרידם ברתיחת הקדושה, והוא אומרם ז''ל (ב''ר פ' ס''ג) כי יעקב יצא נקי ובר וכו'. ומעתה נשקיף במעשה יעקב כי בעת הזרעת ראובן היתה מחשבתו לא שלימה בבחינת הטוב בפרט זה שלא עשה מעשה במקום המחשבה ובחינה זו אינה במדרגת הטוב, וכמו שתמצא שחשבו ז''ל (נדרים כו:) בדומה לזה בני תמורה, והגם כי ישתנה מעשה יעקב לצד כי מחשבתו וידיעתו שלימה פירוש כי היה חושב ברחל גם היה בדעתו ובידיעתו כי היא זאת רחל לא שהיה יודע שהיא לאה וחשב ברחל שלזה יקרא בני תמורה, אף על פי כן הדבר הוא כל שהוא מבחינת לא טהור, וצא ולמד מה שיצא מזה כי יצא ראובן ובלבל יצועי אביו הרי שעשה פעולתו מעשה הבלתי טהור מה שלא עשה כן אחד מכל השבטים ואפילו על ידי נסיון של יוסף. והגם שאמרו רבנן (שבת נה:) כל האומר ראובן חטא אינו אלא טועה, עם כל זה הכתוב העלה עליו החטא או לצד שעשאו או לצד שראוי ליקרא עליו:
@29 **ומה** שתמצא שיהודה שכב עם תמר, ב' תשובות בדבר הא' כי לא ידעה וגם מלאך אנסו כאומרם ז''ל (מכות כג:) בפסוק צדקה ממני שיצתה בת קול ואמרה ממני יצאו הדברים מה שאין כן ראובן דאדרבה התורה העידה כי עשה מעשה בלתי הגון:
@29 **ומה** שראיתי להרב המופלא הר''י רוזאניס זצוק''ל (פרשת דרכים ד''א) שהליץ בעדו כי בלהה היתה מפותת אביו ודייק תיבת פלגש שאינה בקידושין וכו' יע''ש, אין דבריו נראים כי ודאי שבקידושין היו וכמו שפירשתי שם במקומו וכמו שכתוב בקונטרס הראיות, ומה שאמר הכתוב (לעיל ל''ה כ''ב) פלגש אולי שהיא סברת ראובן שבה שגג. או רמז הכתוב טעם בלבולי יצועי אביו שאמר לא די זלזול אמו בפני רחל הגבירה אלא עוד תתזלזל בפני הפלגש, ולעולם אשת יעקב היתה והכתוב העלה עליו ששכב עמה. ומעתה תשכיל לדעת כי דברי הזוהר שאמר שטעם הבכורה הוא כי המחשבה במקומה עמדה ביוסף ומה שאמר הכתוב בדברי הימים ובחללו יצועי אביו וגו' הוא ענין אחד כי החילול יצא מהאמצעות המחשבה שלא היתה בלאה אלא ברחל ואם היתה מחשבתו בלאה לא היה ראובן מחלל יצועי אביו:
@29 **ובזה** נבוא לביאור הכתובים כפתור ופרח, כי יעקב תחילת דברו הטוב כשרצה להסיר הבכורה מראובן עמד לנס לפניו מה שהקדמנו כי תולדות הרע בבנים התחלתה תהיה מהמוליד, לזה חש יעקב שיאמר ראובן בלבו כי יעקב הוא הסובב למעשה ההיא כפי מה שהקדמנו כי המוליד יוליד שרשים בנפש הבן אם לטוב אם לרע, ולצד שחטא ראובן היה בבחינת השכיבה בא להסיר חשד ממנו ואמר **ראובן בכורי אתה** וגו', הנה יש בעוברי עבירה בבחינת הניאוף ג' הדרגות, א) שנואפים ויולדים בנים שלא כהוגן. ב) מזריעים באיסור ואינו מוליד בן מאותה ההזרעה, ויש בגדר זה כמה הדרגות או שבא על אשת איש ולא ילד ממנה ממזר או ששחת בזכר או ששחת ארצה או בחזיונות לילה במקרה, ג) שמתחמם האדם וקשתו ננער באמצעות מחשבות רעות וכדומה, וכל שלש אלה הם מדריגת התיעוב השנאוי בעיני הקב''ה, לזה אמר כנגד שלשתם בכורי וכחי וראשית אוני, **בכורי אתה** שלא ילדתי בן קודם לך שלא בדרך כתובה וקידושין כי זה גם כן מהבלתי נכון, **כחי** שלא יצא ממני זרע קודם לך, **ראשית אוני** שלא ננערה קשתי, הא למדת כי יעקב מושלל מבחינה זו של ניאוף בהחלט:
@29 **גם** רמז באומרו **כחי וראשית אוני** שנוצר מטיפה ראשונה שיצא מיעקב ומזה אתה למד כי לא בעל על הבתולים שאם כן לא היתה מתעברת מביאה ראשונה אלא הוציא בתולים באצבע כדי שלא תפסד הטיפה הא למדת כי גם בשעת מעשה לא הגביר תאווה הגופיית ומעשהו היה לתכלית דבר קדושה, ומעתה אין מקום לחשוד ביעקב ממעשה ראובן כי הוא הסובב, וזו היא תכלית כונתו ולא לשבח עצמו נתכוין:
@29 **ואומרו יתר שאת** וגו' פירוש כי נטילת פי שנים רמז הוא באומרו **בכורי אתה** וסתם בכור נוטל פי שנים אלא הגדולה והכהונה היא מהלכות דרך ארץ ולפעמים תתהפך המעלה למי שראוי לה הגם שיהיה קטן לפני בכור, לזה אמר ויש לך יתרון עוד ליטול הכהונה והמלכות:
@29 **או** ירצה כי לו נאה ליטול ביתרון בחינת הכהונה וביתרון בחינת המלכות יותר מכל הבכורות כי כל הבכורות לא ישוו לבחינת בכורתו של ראובן מהטעמים שאמר יעקב:
@29 **ועד** עתה הרי החזיק עצמו במושלל מבחינת הרע והחזיק הבכורה כי לו לראובן נאה ולו יאה, ואחר כך בא לתת טעם לב' דברים, בין למה שנוגע לגדולה שהוסרה ממנו בין למה שנוגע לבחינת מעשה בלתי הגון מבטן מי יצא הקרח ואמר כנגד מה שנוגע לבכורה וגדולותיה אמר:
@30 **פחז כמים וגו'**. פירוש אתה פחזת לבלבל יצועי ולא כבשת יצרך אלא שמהרת כאיש הפוחז ולא עכבת עצמך לנצוח ניצוץ הרע שנשרש בך, לזה לא יהי' לך יתרון מכל הג' יתרונות ונעשה פשוט, עוד רמז באומרו **אל תותר** שהפחיזות שנהג לעשות דבר בלתי הגון לא נהג לעשותו בדבר שיש בו יתרון, כי לענין תשובה לא קדם הוא לעשות תשובה כאומרם ז''ל (ב''ר פ' פ''ד) מי גרם לראובן שיודה יהודה. והגם שאמרו ז''ל וז''ל לא היה אדם שפתח בתשובה עד שבא ראובן וכו' עד כאן, עם כל זה וידוי לא אמר עד שבא יהודה ואמר צדקה ממני באותה שעה קפץ ראובן ואמר אני בלבלתי מיטת אבי כך הובא במדרש (תנחומא) שכך קבלה בידם. ולדבריהם אלו יש לנו לומר כי לטעם זה נתנה מלכותו של ראובן ליהודה בעד גמר ההודאה אשר גרמו לראובן להודות. והכהונה שנתנה ללוי נראה כי לא זכה בה אלא באמצעות מעשיו אחר כך כאומרו (ברכה ל''ג ח') לאיש חסידך אשר נסיתו במסה וגו' ואז הוא שנתנה ללוי הכהונה, ועל כל פנים מימי יעקב ניטלו כל המעלות מראובן כאומרו **אל תותר** ונתן יעקב ב' מעלות א' ליוסף וא' ליהודה והג' תלויה ועומדת עד שנתנה הקב''ה לראוי לה אשר ניסהו וגו':
@30 **וכנגד** מה שנוגע למעשה בנין שורשו אמר **כי עלית** וגו' פירוש טעם עשותך כן הוא כי בעת שזרעו ועלה בבטן אמו היה בלבול בעליתו כי עלה בב' משכבות לאה ורחל א' במעשה וא' במחשבה, כי במעשה היתה לאה ובמחשבה חשב יעקב כי היא רחל, והוא אומרו **משכבי אביך**, וזה היה סיבה שאז חללת יצועי עלה, כי בחינת הרע תוליד בדמותה כשם שעלה בבלבול כמו כן בלבל יצועי אביו, ולזה דקדק לומר **אז** לרמוז כי לא על זמן שעלה משכבי אביו הוא אומר שחלל יצועי כי הם ב' זמנים שזמן שעלה משכב הוא זמן שעלה בבטן אמו וזמן שחלל הוא אחרי כן:
@31 **שמעון ולוי וגו'**. אומרו **אחים** כי ישנם באחוה בטבעם ודעת אחת שוה כדעת אחים ודבר זה לא ישוה בכל אחים, או ירצה לתת טעם למעשיהם אשר עשו במעשה שכם ובמעשה יוסף ואמר שטבעם בתגבורת יסוד האש. ותמצא שאמרו ז''ל (יומא כב.) שאול באחת ועלתה לו המלוכה ממנו ודוד בכמה ולא עלתה לו, והטעם הוא לצד כי שאול טבעו מזוג ודוד טבעו חם כאומרו (ש''א טז) והוא אדמוני, וה' דן את האדם כפי הרכבתו, כי מי שגובר בו יסוד האש עם היות שיתעצם בכל עוצם הזריזות בעבודת ה' לא ימלט מהשגיון, ובחלק מועט מהתעצמותו שיעשה אדם מזוג ירויח עצמו משגיאות. ואמר כי שמעון ולוי **אחים** לשון חום, ולזה קלל לאפם ועברתם כי קשתה, וידוע הוא כי האף והעברה תגדל מיסוד האש כשיתרבה. ואמר כי לצד שהם בתגבורת החום לזה **כלי חמס מכרותיהם**. ודימה מעשיהם לכלי חמס, לומר כי לא ירשו כליהם משורש נפש המוליד אלא כלי חמס הם דברים המוכרים להם. ופי' **מכרותיהם** לשון הכרה שלא פעל בה להם מאביהם אלא הגברת האש אבל הם מאמצעות דבר זה עשו מעשים בלתי נכונים כמעשה יוסף:
@31 **עוד** ירצה באומרו **כלי חמס** וגו', פירוש המכר שמכרו את יוסף חמס מכרוהו על מה שלא נתחייב להם בדין. והגם שכל האחים מכרוהו כשתשכיל תראה שהם היו העיקר, מתחלה בבואו אמרו איש אל אחיו וגו' ואמרו ז''ל (ב''ר פ' צ''ט) שהם שמעון ולוי והם שיעצו עליו הריגה והכל היה מהם וכן הוא בדברי רבותינו ז''ל:
@32 **בסודם וגו'**. צריך לדעת כוונת הכתוב. ורז''ל אמרו (סנהדרין קט.) בסודם זה מעשה זמרי, בקהלם זה מעשה קרח, כי באפם וגו' זה חמור ואנשי שכם, וברצונם וגו' זה יוסף וכו' (תרגום ירושלמי) ע''כ. ודבדיהם ז''ל דרך דרש וכפי הפשט קשה למה יקדים המאוחר ויאחר מעשה שכם ויוסף שהיו ראשונים:
@32 **עוד** איך יוצדק לאמר תיבת **כי** על ענין בפני עצמו שאין לו שייכות עם למעלה ממנו:
@32 **עוד** למה מיחס עון זמרי גם ללוי והוא אדרבא הנותן נקמות:
@32 **עוד** צריך לדעת כוונת אומרו **וברצונם** למה הזכיר הרצון בזה:
@32 **אכן** פשט הכתוב הוא כי כל הכתוב ידבר במעשה יוסף ואמר **בסודם** פירוש מעת שהתחילו לשנאותו והיה הדבר ביניהם בסוד כשיערימו סוד אל תבא נפשי פירוש לא הסכימה נפש שזרעתי בהם להיות עמהם בהוסדם יחד, והכוונה בזה כי לא מכוחו בא הרע ההוא כמו שכתבנו למע לה:
@32 **עוד** ירצה כי לא יענש על הדבר לצד שעשו בניו ככה. או לצד שהוא גרם קנאתם בשנותו את בנו בין הבנים. **בקהלם** כשנקהלו עליו להורגו דכתיב (ל''ז כ') לכו ונהרגהו וגו' אל תחד כבודי לא יקראו על שמי בני יעקב כל עיקר באותה שעה:
@32 **עוד** ירצה **אל תחד** לשון חדוה כאן רמז ליגונות שעברוהו וסילוק השכינה מעליו שהוא בחינת הכבוד כאומרם ז''ל (תנחומא וישב) שמעת שנאבד ממנו יוסף לא שרתה עליו שכינה מצד העצב והיגון. ואומרו **כי באפם** וגו' פירוש טעם הדבר שאני אומר אל תבוא ואל תחד וגו' כי בהוסדם יחד לקחת נפש זממו, והוא אומרו **הרגו איש**, והגם שמצינו שלא הרגוהו הרי הסכימו על הריגתו והטילוהו אל בור מלא נחשים וגו' למות שם בכמה מיני מיתות:
@32 **וברצונם וגו'**. פירוש אפילו בעת שנח אפם אחר שהשליכוהו בבור וישבו לאכול לחם ודבר להם יהודה דברי רצוי ונחת רוח אף על פי כן עשו רעה שעקרוהו לשור שהוא יוסף שאמרו ז''ל (סוטה נו:) שבאמצעות ירידת מצרים ומקרה רע של אשת פוטיפר נעקרו מיוסף עשרה שבטים שהיה ראוי לילד י''ב ולא נשארו אלא שנים:
@33 **ארור אפם כי עז וגו'**. פירוש לחלק המרובה בהם יותר משיעור הרגיל הוא מקלל וישאר בהם חלק הרגיל בכל אדם כדי לקבל שכר לעולם הבא על כפייתו לעבודת ה' שאם לא כן יושלל מהם בבחינתו אושר המושג לנצח. וראה כי תיקון לקרר עוז הרתיחה הוא לחלקם וגו' ואמר אחלקם וגו':
@34 **יהודה אתה וגו'**. צריך לדעת למה הוצרך לומר **אתה** כיון שעמו היה מדבר ומה בא למעט. עוד למה לא אמר וידך וגו' וישתחוו וגו' כיון שהם דברים נוספים:
@34 **ונראה** שכוונת הכתוב הוא על זה הדרך **אתה יודוך** פירוש אין השררה מתחלת לעתיד כדרך שאר ברכות האמורים לשאר האחים שהם לזמנים רחוקים לכשיכנסו לארץ אלא אתה בעצמך יודוך אחיך, וכן הוא אומר בדברי הימים (א' ה') יהודה גבר באחיו, וכשיבא זמן שידך בעורף אויביך ותתגבר על האויבים אזי ישתחוו לך וגו' וימליכוך עליהם, וזה היה בימי שאול כשעשה דוד הנצחון הגדול בעורף אויביו המליכוהו ישראל עליהם:
@35 **גור אריה וגו'**. רז''ל (זהר ח''א רלז:) אמרו מתחילה גור ואחר כך אריה וצריך לדעת למה הוצרך להזכיר זמן היותו גור. עוד צריך לדעת אומרו **מטרף בני עלית**. ורז''ל אמרו שעל אומרו טרוף טורף הוא אומר לו בני עלית פירוש סלקת עצמך, ולדבריהם ז''ל תתפרש תיבת בני למעלה ולמטה על זה הדרך מטרף בני פי' יוסף עלית, גם על זה הדרך מטרף של יוסף בני פירוש אתה בני עלית, ואמר תיבת בני לשון חיבה וקירוב הלב. אלא שצריך ערב שיעקב חשדו ליהודה לומר עתה עליו שעלה מהחשד והדעת נותנת כי מעולם לא עלה על דעת יעקב שאחים ישלחו יד ביוסף לחשוד אחד מהם, אלא שדברי רז''ל הם דברי קבלה:
@35 **עוד** צריך לדעת אומרו **כרע רבץ** וגו' **מי יקימנו** כי מלבד שאין משמעות לפשטיות הדברים למה דבר לשון נסתר ושינה מסדר שהתחיל לדבר בו בדרך נוכח כאומרו אתה יודוך וגו' בני עלית:
@35 **אכן** יתבארו הכתובים על פי הקדמה אחת זכה וברה אשר האירה עינינו בדברים נחמדים מאור תורתינו, והוא כי אדם הראשון הוא אילן שבו היו תלויים כל הנשמות של הקדושה שיצאו לעולם מיום היות עולם ואשר עתידין לצאת, וכשחטא אדם שלט חלק הרע וישב ממנו שבי לאין מספר, ודרשו מעל ספר אנשי אמת מה עצמו השבויים מהקדושה בקליפה, והן עם ה' משתדלים מיום היותם לברר ולהוציא בולעו מפיו והולכים ומבררים ומוציאים מידו באמצעות מקור הקדושה אשר נטע ה' בתוכנו היא התורה והמצות. גם לפעמים באמצעות דביקות הנפש הקדושה בנפש הטומאה לאונסה תוציא נפש חיה למינה, והוא סוד (וישלח ל''ג) ותדבק נפשו בדינה בת יעקב ששאבה נפש דינה הקדושה לנפש קדושה מינה שהיתה נתונה תוך שכם, ואמרו ז''ל (קהלת יעקב) כי הוא נפש ר' חנינא בן תרדיון. והוא רמז רחב''ת ידים. ולפעמים תצא הנפש מעצמה לעולם לצד השרצת נפשות הקליפה בעולם תצא גם היא ובצאתה תהיה מובדלת מאוצר הקליפה טבעה ותאוה ללכת בדרך הטוב והוא סוד נשמת הגרים המתגיירים מעצמם וחושקים להסתופף בצל הקדושה, ובכלל דבר זה גם כן באמצעות דבר מגונה ביותר יבחר השבאי שהוא אדם בליעל להוציא נפש הקדושה ששבויה בידו במקום קליפה שהיא בחינת העון שיהיה יותר מגונה, וזה לך האות רות המואביה יצתה מזנות אב ובתו ונעמה העמונית, ותבחין לדעת כי רות שיצתה ממנה שלשלת מלכות בית דוד היתה ממואב שהיא בעלת עבירה בחציפות יותר ומעשיה מוכיחות עליה כאומרם ז''ל (ב''ק לח:) ונעמה יצתה מעמון שלא היה העון מזוהם כאחותה. ויש לך לדעת כי אם היה עושה מעשה לוט אדם אחר לא היו יוצאים באמצעותו ב' פרידות הטובות אלא לצד לוט שהיה גדול בבחינתו כי גם בחינת הרע יש בה הדרגות גדולות זו למעלה מזו כפי בחינתה, וצא ולמד מהאומות שהם ענפי הקליפה שיש בהם מלכים גדולים ומלכים קטני הערך ושרים וגו'. והוא סוד אומרם ז''ל (סוטה מט:) בעקבות משיחא כונתם בזה כי לצד שאנו מבררים כל תפיסת הקליפה מהקדושה כשיגיע הבירור לסוף דבר שהוא העקב וכינו התכלית לעקביים כי הוא סוף אברי האדם, ולזה תמצא כי בזמנים הראשונים היו מתבררים מהקליפה נפשות גדולות וצא ולמד האדם הגדול בענקים אבינו ועטרת ראשינו הוא אברהם גר צדק ראשון שבגרים ושרה אמנו ורות המואביה ובדורות אחרונים שמעיה ואבטליון אונקלום הגר, והן היום הגם שמתגיירים להיות שספו תמו ניצוצי הקדושה מתוך הקליפה ולא נשארו כי אם בעקבות, גם כח המברר בבחינה עצמה קטנה והוא סוד אומרם ז''ל בזוהר (ח''א'' רנח.) דנגעו רגלין ברגלין כי כל בחינה תברר בחינתה, ועל פי הקדמה זו תשכיל עצת ה' אשר יעץ על יהודה ושלח מלאך והכריחו לבא אל הקדשה (ב''ר פ' פ''ד) כי באמצעות היות הדבר בלתי הגון על פי התורה לשכב את כלתו ובאמצעות היות יהודה אנום על פי הדיבור נעלם דבר איסור ממנו ולא ידע כי כלתו היא ובזה הוציא ממקור הטומאה ענף מופלא שבקדושה פרץ וזרח שהיו שבוים בבחינת הרע והיה אדם בליעל רובץ עליהם לצד גודל מעלתם, וצא ולמד כמה צדיקים יצאו מהם ושלשלת המלוכה של בית דוד. וזולת יהודה שהוא בחינת המלוכה לא היה אדם יכול להוציאם מידו. גם זולת דמיון מעשה הרע כי יבא אל כלתו אין מציאות להוציאם ובאמצעות דמיון הרע הרי זה נכנם למדור הרע והוציא שלל רב:
@35 **והן** הנה הדברים שאמר הכתוב **גור אריה יהודה** פירוש מתחלה קודם מעשה תמר הוא גור, וזה הוא שרמז בתחלת דבריו באומרו אתה יודוך אחיך מלבד מה שפירשתי במקומו כפי זה יתבאר עוד על זה הדרך **אתה יודוך** פירוש לא היה לך אלא גדולת עצמך שיהיו אחיך כפופים לך אבל לא היתה מדה זו נוהגת לדורות, וצא ולמד מה גדולה היתה לבניו לבד פרץ וזרח שבאו ממעשה הרשת אשר פרש אלהים, ולבסוף אריה שנתגבר ונתעלה, ופירש מנין זכה לעלות מעלה זו ואמר **מטרף בני עלית** פירוש מאותו טרף אדם שטרף בחינת הרע מאדם הראשון נשמות המופלאות ובאמצעות מעשה תמר הרוחת אותם מזה היתה עלייתך וקנית בנים שמלכותם מלכות עולמים שזולת זה לא היה בענפי נשמתך גדולה לדורות אלא לך לבדך:
@35 **ואומרו כרע רבץ** וגו' פירוש כי אותו הטרף שממנו היתה עליתו כרע רבץ עליו אותו שנאמר בו (ד' ז') לפתח חטאת רובץ ולא היה לו מציאות להקימו מעליו ולהוציאו ממנו האבן יקרה, ורמז באומרו **אריה ולביא** כי בחינה שתקפה בנפש הלא היא בחינת ארי ולזה צריך בחינת ארי שבקדושה שהוא יהודה להקימו ולהוציאה מתחת ידו. ומעתה לא יסור שבט מיהודה לעולם מלכותו מלכות כל עולמים כי קנה יסוד המלוכה עד כי יבא שילה שאליו אנו מקוים יום יום צפינו לישועה:
@37 **אוסרי לגפן וגו'**. הן רבו מפרשי כתוב זה וכולן דרך דרש דרשו. ואולי שיכוין עוד לומר על ביאת מלך המשיח האמור בסמוך עד כי יבא שילה וגו' ואמר ולו יקהת עמים שאליו עמים ידרושו אמר שיאסור במאסר ובתפיסה לפני הגפן שהם ישראל שנמשלו לגפן דכתיב (תהלים פ') גפן ממצרים תסיע יאסור לפניהם עירה פירוש כל האומות הנמשלים לחמור דכתיב (יחזקאל כב) אשר בשר חמורים בשרם, וכן דרשו ז''ל (קידושין סח.) בפסוק עם החמור עם המשולים לחמור. ולשורקה פירוש לפני ענף אחד מהגפן הנקרא שורק יאסור גם כן בני אתונו, ודקדק לומר עיר ואתון לצד שיש בבחינת הקליפה שהיא שורש נפשות האומות בחינת זכר ונקיבה ולבחינת זכר יקרא עיר ולבחינת נקבה יקרא אתון. ואמר כנגד הגפן שהוא כללות ישראל אוסרי עירה שהוא בחינת הזכר שהוא תוקף האומות וכנגד ענף אחד מישראל אמר אתונו לומר לצד בחינת הנקבה לא יצטרך לכל ישראל אלא באמצעות ענף אחד די:
@37 **או** יאמר על זה הדרך שהכתוב מדבר בב' הגאולות המפורסמות, הא' היא של מצרים, והב' היא גאולה העתידה בעז''ה, כנגד גאולה הא' אמר **אוסרי לגפן** על דרך אומרו גפן ממצרים תסיע שאז כפה ה' לפניהם בחינה אחת הנקראת עיר והוכנע לפני הגפן וכנגד גאולה הב' בעז''ה שתהיה בימינו אמר **ולשורקה** פירוש בעת אשר ישרוק ה' דכתיב (זכרי' י') אשרקה להם ואקבצם אז בני אתונו אמר לשון רבים לומר כל בחינת האומות כי ביציאת מצרים לא הכניע ה' לפניהם אלא ראש אומות שהם מצרים וכנען שהם ז' עממין שהם היו ראש ותגבורת לכל האומות אבל ע' אומות לא הוכנעו ולא ניתנו להם, אבל לעתיד לבא בעז''ה לא יניח מהאומות אומה גדולה או קטנה שלא תנתן להם, והוא אומרו **בני אתונו** פירוש מלבד עירה אלא גם בני אתונו, ואולי נוכל לומר עוד על דרך מה שאמרו בזוהר (פנחס רלא:) כי בסטרא אחרא הנקבה היא יותר חזקה מהזכר כי הזכר נוטל יותרת שלה ונקרא יותרת הכבד, וכדבר הזה ובחזיון הראוני בחלום שהאבקתי במלחמה עם הזכר ויהי נקל בעיני להכניעו והפלתי אותו בכחי ולנקבה נתאמצתי בכל כחי כמה פעמים ואחר כמה טרחות יכולתי להשליכה כמה מעלות למטה לארץ אך לא כבעלה הזכר, ולזה אמר כנגד גאולה העתידה ולשורקה עת אשר ישרוק ה' ויקבצם בני אתונו אותם שבאים מכח הנקיבה גם אותם יאסור ה' לפני בני ישראל. ולא יקשה בעיניך שאנו מחלקים דברי הכתוב חלק בימי משה וחלק בימי המשיח, כי הלא ידעת דברי הזוהר הקדוש (ח''ב קכ.) כי משה הוא הגואל אשר גאל את אבותינו הוא יגאל אותנו וישיב בנים לגבולם דכתיב (קהלת א') מה שהיה הוא שיהיה ר''ת משה ולא יקשה בעיניך דבר זה באומרך הלא מלך המשיח משבט יהודה מזרעו של דוד המלך ע''ה וי''א (סנהדרין צח:) דוד עצמו מלך המשיח דכתיב (יחזקאל ל''ז) ועבדי דוד מלך עליהם כמשמעו ואם כן היאך אנו אומרים שהוא משה הבא משבט לוי:
@37 **יש** לך לדעת כי בחינת נשמת משה, ע''ה היא כלולה מי''ב שבטי ישראל כי כל הס' ריבוא היו ענפיה ע''ה וענף שבטו של דוד במשה הוא, ולזה תמצאנו בארץ מדבר שהיה מלך וכהן ולוי ונביא וחכם וגבור שהיה כולל כל הענפים שבקדושה ולעתיד לבא תתגלה בעולם שורש המלכות שבמשה שהוא עצמו מלך המשיח והוא דוד והוא ינון ושילה:
@37 **כבס ביין וגו'**. יתבאר על דרך אומרם ז''ל (ז''ח פרשת בראשית) כי גלות ד' שבו יגלה הגואל העצום צריך שתהיה ביד ישראל מצות עסק התורה וזולת זה יתעכב מבוא, ולזה רמז באומרו **כבס** וגו' פירוש כי כחו של המלך המצופה שילה שמו הוא בחינת עסק התורה שיתעסקו ישראל ביינה של תורה, ועיין מה שפירשו בפסוק (שהש''ר פ''ב) הביאני אל בית היין, ואמר כי באמצעותה יהיה לבושו שהוא כינוי למלכות נכון אליו ללובשו, ואומרו **ובדם ענבים** וגו' נתכוין לומר כי אם יגיע זמן הגאולה ולא ימצא יין פי' שאין בנו תורה תהיה הגאולה באמצעות עול ותוקף הגלות אשר יצירון האומות לישראל כאומרם ז''ל (סנהדרין צז:) כי כשיגיע קץ הנחתם ולא יהיה בישראל זכות לגואלם יעמיד להם מלך קשה כהמן וכו', והוא אומרו **ובדם ענבים** כי באמצעות היסורין יזדככו הנפשות ויתבררו ניצוצי הקדושה כדרך שיתבררו באמצעות בחינת התורה אלא שזו מלאכתו נאה וזו מלאכתו בלתי נאה. ואומרו **ענבים** כי באמצעות היסורין תגמר הכנתה כגמר בישול פרי הגפן שהם הענבים. וגם רמז כי לא ישלטו האומות לשפוך דם לזמור אילן או ענף או אשכול אלא ענבים פירוש גרגרין. ואמר **סותה** לרמוז מדרגה קטנה למטה מהכסות כי הסות ירצה לשון כיסוי ההכרחי לשון מסוה, והכוונה בזה כי הפרש גדול יהיה בין אם תהיה הגאולה באמצעות התורה והמצות אז יגלה בגילוי מלכות עליון ותהיה באמצעות הנקמה אשר תהיה בישראל יהיה בבחינת עני ורוכב וגו':
@38 **חכלילי עינים וגו'**. יכוין על דרך אומרו (תהלים ס''ח) מוציא אסירים בכושרות ודרשו ז''ל (במד''ר פ''ג) בכי ושירות בכי למצרים ושירות לישראל, והוא אומרו **חכלילי עינים** לשון אדמימות שהוא ענין הדינים שכל האדמימות יורה על עוצם המשפט כי דמים בדמים נגעו. ואמר **מיין** פירוש ממקור הדין שהוא היין. או ירמוז סיבת הנקמה היא מיין פירוש מצד מה שחבלו ופשעו בני תורה מללמוד לבי לבי על דבר זה מעי מעי על אשר מנעו בני עולה אותנו מעסוק בתורת אל חי ועל זה ינקום נקום בהתעוררות תגבורת הדינים. ובזמן עצמו **ולבן שינים מחלב** יראה לנו לובן שינים מחלב ואולי שירמוז באומרו ולבן על ישראל שקראו ה' בן דכתיב (ירמי' ל''א) הבן יקיר לי. ואומרו **מחלב** הוא בחינת החסד והרחמים אשר יעורר עלינו אבינו הזמן עצמו שהוא נוקם נקם, והוא אומרו (מיכה ז') כימי צאתך וגו' כשם שאז היה בכי ושירות כמו כן יהיה במהרה בימינו אמן:
@40 **יששכר וגו'**. אומרו **חמור גרם** פירוש יציאת אמו על ידי שנער החמור (נדה לה) זה היה סיבה שיששכר רובץ בין המשפתים ואינו מיושב תמיד במקומו, והוא טעם שבני תורה שהם ענפי יששכר יסובבו מעיר לעיר כי המעשה הבלתי נכון יוליד ענפיו והיא לאה עשתה דבר שהוא למראית העין חוץ מדרך המוסר גם היוצא ממנה ימצאנו כדרך זה, ואף על פי כן חפצים בעמלה של תורה בנועם. **וירא מנוחה כי טוב** פירוש מנוחה העליונה, כי טוב פירוש בהביט ובהתבונן האדם בכל הנאות העולם הזה הנרגשות כמו שתאמר תאות המאכל והמשתה אין העריבות של אותו דבר צודק מצד עצמו אלא מצד הגוף אשר הוא כלי ריקם שעומד למלאות שכן הטביע בו היוצר שלא יוכל להתעכב ריקם כלל, ולזה כאשר יהיה האדם שבע לא מלבד שלא יקח עריבות למאכל ההוא אשר נכספה וגם כלתה נפשו אליו באותה שעה עצמה קודם שמילא כריסו אלא שמואם בו כמואם ברע, וזהו שאמר הכתוב (משלי כג) פתך אכלת תקיאנו פירוש הפת של העוה''ז אם אכלת אותו אחר כך תקיאנו כי תמאס מהכניסו לתוך פיך, גם בדבר אשר יחשוק בו האדם למראית העין ויתאו לבריה נעימה כאשר יחקור בטיב החקירה יראה שאותו יופי ונעימות אינו אלא מראה היולי כי בהתבונן האדם בבשר ובעור אשר מהם בנוי כל יופי ותואר באדם יראה וישכיל בהתבונן בהם כי אין בהם נעימות ויתמאס בבשר אדם מגשת אליו ואין הכל אלא דמיון, אבל הטוב האמיתי והנעימות הצודק הוא של עולם העליון, ולזה אמר **וירא מנוחה כי טוב** פירוש העולם שנקרא מנוחה שהיא טובה לשלול הטוב הנדמה בעוה''ז כנזכר **ואת הארץ כי נעמה** כפי האמת. **ויט שכמו לסבול** צער העוה''ז **ויהי למס** פירוש שהיה הוא עצמו מם עובד פירוש שפינה עצמו לעבוד ה' ועשה עצמו כמם הניתן כן נתן עצמו להיות עובד עבודת הקודש העריבה והנעימה:
@40 **עוד** ירמוז באומרו **ויהי למס** עובד שכל הנבראים יעלו לו מם לפרנסתו ויעבדוהו לבן תורה וכמו שמצינו ליששכר עצמו שהיה זבולן עובד אותו וכן בכל דור ודור:
@42 **דן ידין וגו'**. אולי כי לצד שאמר שמשון (שופטים טז) תמות נפשי עם פלשתים לזה אמר יעקב כי ישנו בגדר עם שופטי ישראל המיוחדים למעלה באין הפרש ולא יגרע מצדיק עינו והוא אומרו **כאחד שבטי ישראל** פירוש כאחד המיוחד שבכל שבט ושבט מישראל כי כל השבטים היו בהם שופטים לישראל:
@45 **גד גדוד** וגו'. מבליע ברכתו בשמו ופירוש גד לשון גדוד פירוש מחנה ולשון גדייה. ולשון משיכה, ולשון היקף שכולם במשמעות גד, ועיין בערוך בפירוש תיבת גד. ואמר **גד גדוד** אויביו יסובבוהו על גדותיו, **והוא יגוד** פירוש יכרות אותם עקב פירוש עד כלה. עוד ירצה **גדוד** פירוש לשון מחנה שיתרבו גדודיו ויהיה מחנהו משוך והולך, והוא אומרו יגודנו, ואומרו **והוא יגוד** פירוש יקיף לכל מחנה ישראל וילחם בעדם. עקב פירוש עד שינחלו כל נחלתם:
@46 **מאשר שמנה וגו'**. אולי שיכוין לומר כי השגה זו מאמצעותו השיג אותה והוא אומרו מאשר וגו' פירוש מצדו או מצד זכותו או מצד השתדלותו:
@48 **בן פורת יוסף**. טעם הכפל הוא לומר כי לב' צדדין ראוי הוא לפרות, הא' לצד מה שהוא יוסף כאומרם ז''ל (סוטה לו:) ראוי היה יוסף להעמיד י''ב שבטים, והב' בן פורת עלי עין על אשר לא זנה אחרי עיניו. ואומרו **בנות צעדה** יתבאר על דרך אומרם ז''ל (תנחומא) שאשת פוטיפר קראה כל נשי השרים והגדולים והכניסה יוסף לשרת לפניהם וקבוצם והקפם היה כאצעדה זו, **עלי שור** כדי להביט בו, אף על פי כן רוח הקודש מעידה עליו שלא הביט און, וכשם שהוא לא הסתכל בהם כמו כן לא תשלוט עין הרע בו:
@49 **וימררוהו ורובו וגו'**. פירוש מתחלה חשבו להרגו דכתיב (לעיל ל''ז כ') לכו ונהרגהו, או על דרך אומרם ז''ל (ספר הישר פ' וישב) כי קודם שהשליכוהו לבור כשהפשיטוהו חבלו בו כמה חבלות והצרו לו וכנגד זה אמר **וימררוהו**, ואחר כך נתיעצו עליו להשליכו לבור ולמוכרו לנכרים וכנגד חלוקות אלו אמר **ורבו** פירוש הרבו להצר, **וישטמוהו בעלי חצים** היא אשת פוטיפר וחברותיה המוסבות במסיבתה שבקשו ממנו חיציו שהוא זרע היורה כחץ. או אולי יכוין כל הכתוב על פרט זה **וימררוהו** הם בחינת הרע המפתה לעשות רע וזה היה לו סיבה שיפוזו זרועי ידיו לצד שנכנם בגופו היצר הרע וכמעשה (קידושין פא.) רב עמרם חסידא, והנה בחינת הקליפה יתיחס לה שם מרה לזה אמר וימררוהו כוחות הרע. **ורבו** על ידי שרבו כוחות הרע עליו ואנסוהו על העבירה ורבו על המונע וישטמוהו בעלי חצים הם הקליפות אשר מחטיאים את האדם להוציא זרע לבטלה היורה כחץ ואמר לשון משטמה כי כוחות הרע יחשבו לרעה כמשטמים לקדושה להשחית חמדה ואף על פי כן נתגבר כארי ולא ירה חצו אלא ויפוזו זרועי ידיו. ואומרו **מידי אביר יעקב** פירוש כי ה' עזרו על דרך אומרו (תהלים לז) ה' לא יעזבנו בידו ונתן לו אבירות כנגדם כי ה' הוא העוזר נגד המסית והמדיח. ואומרו **משם רועה אבן ישראל** כאן רמז (תהלים קיח) אבן מאסו הבונים ויוסף באמצעות צדקו אשר שמר ברית קודש זכה באבן הראשה. והוא סוד (משלי י) צדיק יסוד עולם שנקרא רועה אבן ישראל והבן ומשלו נתנו לו:
@51 **מאל אביך וגו'**. פירוש כי מאלהי אביו הוא שהשיג המושג אליו, ורמז כי בזכות אביו היה הדבר. והתפלל שכמו כן תמיד יהיה בעזרו, והוא אומרו **ויעזרך**. ואומרו **ואתשדי** פירוש גם שם שדי שהוא השם שבסעד בחינת נפש יוסף כידוע למביני סודי התורה גם זה היה בעזרו להצילו מבת אל נכר וברכו בו:
@51 **עוד** ירצה באומרו **ויעזרך ויברכך** על זה הדרך שהגם שאל עזרו ושדי שגבו להנצל מן החטא אף על פי כן מחזיקים לו טובה על הדבר והם בעזרו ומברכין אותו כאלו ממנו היה הדבר. ולך נא ראה מה שפירשתי (תהלים לז) בפסוק ה' לא יעזבנו בידו ולא ירשיענו בהשפטו:
@51 **ובדרך** רמז ירמוז הכתוב על דרך אומרם ז''ל (ברכות י.) התולה בזכות אחרים תולין לו בזכות עצמו, והוא אומרו **מאל אביך** תלית ההטבה המושגת לך שהיא מזכות אביך בזה ויעזרך פירוש יתכנה העזר לך בזכותך:
@51 **עוד** ירמוז על דרך אומרם ז''ל (ב''ב נח.) אין עושין נס אלא למי שעתיד לעמוד בצדקו, והוא אומרו **מאל אביך** היה לך דבר זה ומעתה **ויעזרך** לבל תכשל בדבר כיעור להעמיד ניסו במקום נאמן:
@53 **בנימין זאב יטרף**. נתכוין אל שאול שעשה מעשה זאב שטורף במהירות כי מנהג הזאב הוא שאינו מתעכב בטריפתו אלא כל כך הוא ממהר וטורף, כמו כן עשה הוא ולא המתין לזמן שקבע לו שמואל אלא מהר (ש''א י''ג) לטרוף ומזה היה סיבה שלא אכל אלא בבקר ונפסקה מלכותו. ואומרו **ולערב** פירוש לעת ערב מלכותו יחלק שיאמרו (שם י''ח) הכה שאול וגו' ודוד ברבבותיו. או ירמוז שבאמצעות סיבתו תתחלק מלכות בית דוד על דרך אומרם ז''ל (יומא כב:) כשאמר דוד אתה וציבא תחלקו השדה יצתה בת קול ואמרה רחבעם וירבעם יחלקו המלכות, ומאז העריב שמשן של ישראל בעונות:
@54 **כל אלה שבטי וגו'**. צריך לדעת מנין זה של י''ב, אם לוי בכלל, אם כן אין הכתוב מונה ליוסף אלא באחד ויעקב אמר אליו (מח ה) אפרים ומנשה כראובן ושמעון, ואם אין לוי בכלל כמו שמצינו שהכתוב לא מנאו בחומש הפקודים בחשבון י''ב שבטים שבדגלים ג' בכל דגל קשה למה יגרע לוי מברכת אביו, ואם לצד שלא מצינו לו אלא קנטור ולא אמר אלא המבורכים אם כן לא יבא במנין גם ראובן ושמעון. ואולי כי לא התחיל הכתוב למנות אפרים ומנשה במנין שנים עד אחר יציאת מצרים וכאן מנה הכתוב יוסף וזה דוחק. והנראה לומר בזה הוא כי לצד שאמר הכתוב איש אשר כברכתו ברך וגו' ומצינו שיעקב כלל שמעון ולוי בכלל אחד לזה מנה שניהם באחד:
@54 **אשר דבר וגו' ויברך וגו'**. הגם שראינו שלא ברך ראובן ולא שמעון ולא לוי, יגיד הכתוב כי דבורו הקשה להם היא ברכתם והוא אומרו **אשר דיבר** וגו' **ויברך** וגו' ומה שאמר לראובן דברי קנטור שם צוה את הברכה על דרך אומרם (ספרי בהעלותך) עתידה עבודה שתחזור לבכורות, וכפי זה כיון שקבע לו שם הבכורה עתיד הוא לעמוד לשרת לעתיד לבא ותמצא שהצדיקים צופים ומביטים על העתיד, ולטעם זה השתדל יעקב לקנות הבכורה מעשו לבל יהיה לו חלק בעבודה לעתיד לבא. והגם שנתנה העבודה ללוים שקולים הם ויבואו שניהם לעבוד עבודת הקודש כי מעלין בקודש ולא מורידין. וגם שמעון ולוי ברכם במה שאמר ארור אפם זו היא ברכתם שקלל לתגבורת המקלקל ומריע גם מה שחלקם והפיצם הוא להשגת תכלית האושר גם כן:
@54 **אשר כברכתו**. פי' הראוי לו כפי בחינת נשמתו וכפי מעשיו, כי יש לך לדעת כי הנפשות כל אחת יש לה בחינת המעלה יש שמעלתה כהונה ויש מלכות ויש כתר תורה ויש גבורה ויש עושר ויש הצלחה, ונתכוין יעקב בנבואה לברך כל אחד כפי ברכתו הראוי לה המלך במלכות והכהן בכהונה וכן על זה הדרך ולא הפך המסילות:
@54 **ברך אותם וגו'**. אמר **אותם** לשון רבים להיות כי ברכת כל אחד ואחד תועיל לעצמו ולכל אחיו כמו שתאמר כשיברך למלך שידו בעורף אויביו הנה מגיע הטוב לכל אחיו. וכן כשירבה מעלת אחד ושפעו והדרגתו לכל אחיו יגיעו גם כן מקצת דבר, לזה אמר **איש אשר כברכתו ברך אותם**:
@55 **ויצו אותם וגו'**. להיות שמקודם קרא לבנו ליוסף והשביעו להתטפל בקבורתו שלא יחשבו שלא חייב אלא יוסף בלבד ולא להם לזה צוה לכולם יחד כי כולן יתעסקו בו. ולא הוצרך להשביעם כי הם יעשו כדבריו כמו שפירשתי בדברי יוסף שאמר ליעקב (מז ל) אנכי אעשה כדבריך:
@57 **שמה קברו וגו'**. להיות שהמערה בעלה הראשון היה עפרון לזה אמר שמה קברו את אברהם ואת שרה הרי נתמעטו בעליה הראשונים ועמדו יורשי אברהם שהם יצחק וישמעאל. **שמה קברו את יצחק** וגו' נתכוין למעט חלק ישמעאל ועמדה ליורשי יצחק שהם יעקב ועשו, **שמה קברתי את לאה** בא למעט עשו, והעד בקברי אשר כריתי לי ודרשו ז''ל (סוטה יג.) וכו':
@58 **מקנה השדה וגו'**. אחר שרמז להם הקנאת זכות המערה לו לבדו חזר על פרט אחד שישנו בערעור על המערה והם בני חת שיכולין לערער מדינא דבר מצרא ויוציאנה מידם, והגם שכפי הדין אין דין המצר בלוקח מן הגוי, זה דוקא אם המערער ישראל והטעם כמו שאמרו בש''ס (ב''מ קח:) דא''ל אריא אברחי לך ממצרך אבל במציאות שלפנינו אין טעם זה צודק, והגוים יטענו דין המצר להוציא מיד בני יעקב, ולערך טענת מצר לא יספיק מה שקבר אברהם ושרה ויצחק ורבקה וכו', וכמו שכתב רמב''ם בפרק י''ג מהלכות שכנים שבין בנה בין חפר וקלקל הרי הוא כשליח ומנכה לו אם קלקל. לזה אמר מקנה השדה מאת בני חת באופן שאין להם דין בר מצרא, ועיין מה שכתבתי בפרשת חיי שרה, וטעם שלא סדר הכתוב פרט זה סמוך לקנייה מעפרון, כי אין קנייתו מבני חת בגדר ושיעור קנייתו מעפרון כי עפרון הוא בעלים הראשונים שקנה מידו אברהם ובני חת אינן אלא כת שיש בהם מיחוש ערעור מדין בר מצרא, לזה בא דבריהם באחרונה:
@59 **ויכל יעקב לצוות וגו'**. הא למדת שלא על יעקב נאמר (קהלת ח') ואין שלטון ביום המות שהיה הדבר ברצונו וברשותו עד שכלה לצוות לבניו כרצונו ואז **ויאסוף רגליו** וגו' והוא מאמר רז''ל (תענית ה:) יעקב אבינו לא מת, שאילו שלט בו המות לא היתה לו שליטה עד עת יחפוץ לאסוף רגליו, וצא ולמד מה שאמרו ז''ל בפי' פסוק (קהלת פ''ח) ואין שלטון שאין מי שיתלה אונקלומא וכו':
@60 **וישק לו**. פירוש לו נשק אבל אין נכון לעשות כן למת אחר כי המת גדוש בטומאה וטומאתו בוקעת ועולה עד לרקיע ותפגם הנפש הנושקת אלא לו ליעקב כי חי הוא אלא דורמיטא קראתו כישן ונרדם:
@61 **ויחנטו הרופאים**. עשה כן יוסף משום כבוד אביו כי כן משפט הנכבדים ומכל שכן גדולי המלכות, או כדי שלא יטעו בו כשלא יחנטוהו שלא מת או שמת ולא הסריח ויעשוהו אלוה כי הוא פלא בעמים המזוהמים וסובב לבלתי יעלהו לארץ קבורתו, ואם לא היה טעמים הנזכרים הדבר פשוט כי בלא חניטה לא היה מסריח, וצא ולמד ממעשה ר' אלעזר ברשב''י כאמור בש''ס (ב''מ פד:):
@61 **או** אפשר לומר כי לצד שישראל שעמדו על הר סיני פסקה זוהמתן (שבת קמו.) ולזה צדיקי ישראל מאז והלאה לא היו מסריחין אחר מותם ואפילו עיפוש הנשאר בבטן יבש ויהיה לעפר כי זוהמת הגוף היא המסרחת אוכל שבמעים מה שאין כן קודם לכן, והגם שנאמר שגופו של יעקב לא יסריח כי לא מת אבל על כל פנים עיפוש המאכל אשר ישאר בגוף האדם כנום כי ירבו לו הימים יתעפש ויסריח ולזה חש יוסף וצוה לחנוט:
@61 **או** אפשר כי יוסף לא ידע מסוד זה וצוה לחנוט:
@63 **אל בית פרעה לאמר**. פירוש שגם סדר דברו אליהם יאמרו אל פרעה כי הוא חילה פניהם בסדר זה ויט בזה חינו בעיני פרעה. או יאמר על דרך אומרם ז''ל (יומא ד.) מנין לאומר לחבירו דבר שהוא בבל תאמר עד שיאמר לו אמור. דכתיב וידבר ה' וגו' לאמר, כמו כן במה שלפנינו הרשם שיאמרו סדר הדיבור אשר דיבר להם בדרך זה לבית פרע ה:
@63 **אם נא מצאתי**. פירוש נא לשון בקשה וזמן כי אין מציאות להראות ליוסף חיבה וחינות כי אם בעת ובעונה הזאת כי לא היה צריך להם לשום דבר:
@63 **דברו נא**. פירוש עתה תכף ומיד כי היה ירא לאחר קיום השבוע ה:
@63 **באזני פרעה לאמר**. טעם אומרו **לאמר**, נתכוון שהם יאמרו גם כן מעצמם לרצות פרעה על הדבר לעשותו:
@64 **השבעני לאמר**. רז''ל דרשו (סוטה) וא''ת נתיר שבועה גם שבועתך היא בהתרה, וכפי הפשט אומרו **לאמר** כי לא היתה השבועה בלשון עצמו האמור בדברי יוסף להם אלא כונת השבועה, לזה אמר תיבת לאמר לומר שכונת מה שאמר בשבועה היא וגו':
@64 **ובדרך** דרש אפשר שנתכון לשלול טענת פרעה כי יאמר אליו למה לא נמלך עמו קודם השבועה ועשה דבר חוץ מהמלכת המלך, לזה אמר לו כי לא היה לו זמן להמלך כי אמירת השבועה היתה סמוך למיתת אביו, והוא אומרו **השביעני לאמר הנה אנכי מת** פירוש בשעה שהשביעני לא נתן לי זמן אלא אמר לי הנה אנכי וגו', וכן היה כמו שפירשתי בפסוק (מ''ז כ''ט) שים נא ידך וגו' שלא נתן לו זמן ארוך ואמת יהגה חכו של יוסף:
@73 **וכל העולים וגו' אחרי קברו וגו'**. אומרו כל העולים לומר שלא נעדר מהם איש מכל המחנה הכבד גם רכב גם פרשים, ונתן הטעם כי כולם הלכו לדבר מצוה לקבור את אביו ולא חזר אחד מהם עד שקבר יוסף את אביו, והוא אומרו **וישב** וגו' **וכל העולים** וגו' כולם שבו, והטעם אחרי קברו שכולם היתה הליכתם לדבר מצוה ושלוחי מצוה אין ניזוקים לא בהליכתם ולא בחזרתם (פסחים ח:):
@73 **או** ירצה על זה הדרך **וישב יוסף** וגו' וכל העולים ותדע באיזה עולים אני מרבה הכל שלא נעדר מהם איש אותם שהיתה כוונת עלייתם לקבור את אביו ובמה יהיו ניכרים אלו מאלו, לזה גמר אומר **אחרי קברו את אביו** אלו שנתעכבו עד אחרי קברו וגו' מחשבתם ניכרת מתוך מעשיהם כי לשם מצוה באו ואותם לא מת עד אחד, אבל העולים לסיבה אחרת אינם בכלל הדבר:
@74 **לו ישטמנו וגו'**. פירוש דלמא אלא שאין חבר לה בכל התורה וצריך לדעת למה ידבר הכתוב לשון זה שמשמעותו הרגיל הוא הפך הכוונה, והגם שאין מקום לטעות להבין בו זולת דלמא, אף על פי כן היה לו לומר לשון צודק פן או אולי. ונראה כי הכתוב דברי עצמו קאמר לו, והכוונה בזה שהם יראו על דבר שהלואי שיהיה כן שיהיה משיב להם והוא אומרו **ישיב לנו את כל הרעה** והיו מצטערים השבטים כשיעור שנצטער יוסף מצדם ובזה לא היו מתחייבים לבסוף מהגלויות ומהצרות בעד חטא זה כאומרם ז''ל (שבת י:) גלות מצרים וגם בגלות האחרון, וצא ולמד מה היה לעשרה עמודי עולם:
@75 **ויצוו אל יוסף וגו'**. צריך לדעת טעם אומרו **לאמר**, ואם הכוונה לאמר ליוסף, היה לו לומר לאמר אל יוסף. ואולי שנתכוונו שלא יאמר לו האומר כי האחים שלחוהו על הדבר אלא יאמר שהוא שמע מאביו מצוה. להאחים לומר אליו הדברים האמורים. וזה הוא אומרו פעם ב' **לאמר** והבן:
@78 **כי התחת אלהים וגו'** פירוש אם אתם חייבים עונש על הדבר אלהים שופט ולא אקום ולא אטור. וטעם שלא מחל להם, אפשר לצד שבני נח אין הדבר תלוי במחילתם כי יחטא אדם לחבירו כמו שתאמר גזלו ומחל הנגזל אינו פטור הגזלן ממיתה, או אפילו ישראל אם גנב ישראל ומכרו אין ביד הנגנב לפוטרו לגנב ממות. ואמר עוד להם כי יש לדון להם משפט זכות:
@79 **ואתם חשבתם וגו' אלהים חשבה לטובה**. והרי זה דומה למתכוון להשקות חבירו כוס מות והשקהו כוס יין שאינו מתחייב כלום והרי הם פטורים וזכאים גם בדיני שמים:
@79 **חסלת פרשת ויחי**:
@79 **סליק ספר בראשית**
